import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface TrainerScores {
  knowledge: number | null;
  didactics: number | null;
  preparation: number | null;
  engagement: number | null;
  culture: number | null;
}

export interface SurveyRecord {
  id: string;
  trainingTitle: string;
  date: string;
  place: string;
  ratings: {
    organization: number | null;
    methods: number | null;
    practicality: number | null;
    materialsClarity: number | null;
    materialsMerit: number | null;
  };
  trainerRatings: {
    luiza: TrainerScores;
    krzysztof: TrainerScores;
    anna: TrainerScores;
    tomasz: TrainerScores;
  };
  comments: {
    positive: string;
    negative: string;
    suggestions: string;
  };
  fileName?: string;
}

export interface GlobalAnalysis {
  avgOrganization: number;
  avgMethods: number;
  avgPracticality: number;
  avgMaterialsClarity: number;
  avgMaterialsMerit: number;
  trainerAverages: {
    [key: string]: TrainerScores;
  };
}

export enum AppTab {
  UPLOAD = 'upload',
  SUMMARY = 'summary',
  TABLE = 'table',
  EDA = 'eda'
}

import { GoogleGenAI, Type } from "@google/genai";
import { SurveyRecord } from "../types";

const SYSTEM_INSTRUCTION = `
You are an expert OCR and data extraction assistant specialized in Polish training evaluation surveys from "QUEST".
Your task is to analyze images of handwritten/circled surveys and extract data into a structured JSON format.

A survey typically spans two pages. 
- Page 1 contains Title, Date, Place, and numerical ratings (1-6) for organization, methods, practicality, and trainers (Luiza, Krzysztof, Anna, Tomasz).
- Page 2 contains comments: "Szczególnie pozytywnie oceniasz", "Szczególnie negatywnie oceniasz", and suggestions.

CRITICAL RULES:
1. Ratings are numbers from 1 to 6. If a number is circled, that's the rating.
2. If multiple pages are provided, combine them into one record if they belong to the same person/session, or return multiple records if they are different surveys.
3. Transcribe handwritten Polish text exactly.
4. If a field is empty, use null for numbers or an empty string for text.
5. In "Ocena trenera", extract ratings for all 4 named trainers if present.
`;

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    surveys: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          trainingTitle: { type: Type.STRING },
          date: { type: Type.STRING },
          place: { type: Type.STRING },
          ratings: {
            type: Type.OBJECT,
            properties: {
              organization: { type: Type.NUMBER },
              methods: { type: Type.NUMBER },
              practicality: { type: Type.NUMBER },
              materialsClarity: { type: Type.NUMBER },
              materialsMerit: { type: Type.NUMBER }
            }
          },
          trainerRatings: {
            type: Type.OBJECT,
            properties: {
              luiza: { 
                type: Type.OBJECT, 
                properties: { 
                  knowledge: { type: Type.NUMBER }, 
                  didactics: { type: Type.NUMBER }, 
                  preparation: { type: Type.NUMBER }, 
                  engagement: { type: Type.NUMBER }, 
                  culture: { type: Type.NUMBER } 
                } 
              },
              krzysztof: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              anna: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              tomasz: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } }
            }
          },
          comments: {
            type: Type.OBJECT,
            properties: {
              positive: { type: Type.STRING },
              negative: { type: Type.STRING },
              suggestions: { type: Type.STRING }
            }
          }
        }
      }
    }
  }
};

export async function processSurveyImages(base64Images: string[]): Promise<SurveyRecord[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const imageParts = base64Images.map(data => ({
    inlineData: {
      mimeType: 'image/jpeg',
      data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          ...imageParts,
          { text: "Analyze these evaluation surveys and extract all data following the provided schema. Return the surveys found." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const result = JSON.parse(response.text || '{"surveys": []}');
    return (result.surveys || []).map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}`
    }));
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

import React, { useState } from 'react';
import { processSurveyImages } from '../services/geminiService';
import { SurveyRecord } from '../types';

interface SurveyUploaderProps {
  onDataLoaded: (data: SurveyRecord[]) => void;
}

export const SurveyUploader: React.FC<SurveyUploaderProps> = ({ onDataLoaded }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve(base64);
      };
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    setIsProcessing(true);
    setError(null);
    setProgress(10);

    try {
      const fileList = Array.from(files);
      const base64Files = await Promise.all(fileList.map(fileToBase64));

      setProgress(30);

      // Batch processing: Gemini handles multiple images well.
      // We process them in chunks of 5 images to avoid token limits if many are uploaded.
      const CHUNK_SIZE = 5;
      const allExtractedSurveys: SurveyRecord[] = [];

      for (let i = 0; i < base64Files.length; i += CHUNK_SIZE) {
        const chunk = base64Files.slice(i, i + CHUNK_SIZE);
        const results = await processSurveyImages(chunk);
        allExtractedSurveys.push(...results);

        const currentProgress = 30 + Math.floor(((i + chunk.length) / base64Files.length) * 60);
        setProgress(currentProgress);
      }

      onDataLoaded(allExtractedSurveys);
      setProgress(100);
    } catch (err) {
      setError("Failed to process images. Please check your API key and image quality.");
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-8 border border-slate-200">
      <div className="max-w-xl mx-auto text-center">
        <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-file-invoice-dollar text-3xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Upload Survey Photos</h2>
        <p className="text-slate-500 mb-8">
          Upload clear photos or scans of training evaluation surveys. Our AI will automatically extract ratings and handwriting.
        </p>

        {!isProcessing ? (
          <label className="relative group cursor-pointer">
            <div className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 group-hover:border-orange-400 rounded-xl p-10 transition-colors">
              <i className="fa-solid fa-cloud-arrow-up text-4xl text-slate-400 group-hover:text-orange-500 mb-4"></i>
              <span className="text-slate-600 font-medium">Click to select files</span>
              <span className="text-slate-400 text-sm mt-1">PNG, JPG up to 10MB</span>
            </div>
            <input 
              type="file" 
              multiple 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileUpload}
            />
          </label>
        ) : (
          <div className="space-y-4">
            <div className="h-4 bg-slate-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-orange-500 transition-all duration-500" 
                style={{ width: `${progress}%` }}
              ></div>
            </div>
            <p className="text-slate-600 font-medium animate-pulse">
              {progress < 30 ? "Initializing AI model..." : "Analyzing handwriting & ratings..."}
            </p>
          </div>
        )}

        {error && (
          <div className="mt-6 p-4 bg-red-50 text-red-700 rounded-lg flex items-center gap-3">
            <i className="fa-solid fa-circle-exclamation"></i>
            <span className="text-sm font-medium">{error}</span>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { SurveyRecord, GlobalAnalysis } from '../types';

interface SummaryDashboardProps {
  surveys: SurveyRecord[];
}

export const SummaryDashboard: React.FC<SummaryDashboardProps> = ({ surveys }) => {
  const calculateAverages = () => {
    const total = surveys.length;
    if (total === 0) return null;

    const sum = (arr: (number | null)[]) => arr.reduce((a, b) => (a || 0) + (b || 0), 0);
    const avg = (arr: (number | null)[]) => {
      const valid = arr.filter(v => v !== null);
      return valid.length ? sum(valid) / valid.length : 0;
    };

    return {
      org: avg(surveys.map(s => s.ratings.organization)),
      meth: avg(surveys.map(s => s.ratings.methods)),
      prac: avg(surveys.map(s => s.ratings.practicality)),
      clar: avg(surveys.map(s => s.ratings.materialsClarity)),
      merit: avg(surveys.map(s => s.ratings.materialsMerit)),
    };
  };

  const avgs = calculateAverages();

  if (!avgs) return <div>No data to display.</div>;

  return (
    <div className="space-y-8">
      {/* Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        {[
          { label: 'Organizajca', val: avgs.org, icon: 'fa-sitemap' },
          { label: 'Metody', val: avgs.meth, icon: 'fa-brain' },
          { label: 'Praktyka', val: avgs.prac, icon: 'fa-tools' },
          { label: 'Przejrzystość', val: avgs.clar, icon: 'fa-eye' },
          { label: 'Merytoryka', val: avgs.merit, icon: 'fa-book' },
        ].map((item, idx) => (
          <div key={idx} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col items-center">
            <div className="w-10 h-10 bg-orange-50 text-orange-500 rounded-lg flex items-center justify-center mb-3">
              <i className={`fa-solid ${item.icon}`}></i>
            </div>
            <span className="text-2xl font-bold text-slate-800">{item.val.toFixed(2)}</span>
            <span className="text-xs text-slate-400 uppercase font-semibold tracking-wider mt-1">{item.label}</span>
          </div>
        ))}
      </div>

      {/* Comments Sections */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white rounded-xl shadow-sm p-6 border border-slate-200">
          <h3 className="text-lg font-bold text-green-600 mb-4 flex items-center gap-2">
            <i className="fa-solid fa-face-smile"></i> Pozytywne Komentarze
          </h3>
          <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
            {surveys.map((s, i) => s.comments.positive && (
              <div key={i} className="p-4 bg-green-50 rounded-lg border border-green-100 text-slate-700 text-sm italic">
                "{s.comments.positive}"
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6 border border-slate-200">
          <h3 className="text-lg font-bold text-red-600 mb-4 flex items-center gap-2">
            <i className="fa-solid fa-face-frown"></i> Negatywne Komentarze
          </h3>
          <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
            {surveys.map((s, i) => s.comments.negative && (
              <div key={i} className="p-4 bg-red-50 rounded-lg border border-red-100 text-slate-700 text-sm italic">
                "{s.comments.negative}"
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm p-6 border border-slate-200">
          <h3 className="text-lg font-bold text-orange-600 mb-4 flex items-center gap-2">
            <i className="fa-solid fa-lightbulb"></i> Sugestie Uczestników
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {surveys.map((s, i) => s.comments.suggestions && (
              <div key={i} className="p-4 bg-orange-50 rounded-lg border border-orange-100 text-slate-700 text-sm">
                {s.comments.suggestions}
              </div>
            ))}
          </div>
      </div>
    </div>
  );
};

import React from 'react';
import { SurveyRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar } from 'recharts';

interface EDADashboardProps {
  surveys: SurveyRecord[];
}

export const EDADashboard: React.FC<EDADashboardProps> = ({ surveys }) => {
  const prepareScoreDistributionData = () => {
    const scores = [1, 2, 3, 4, 5, 6];
    return scores.map(score => ({
      score: score.toString(),
      count: surveys.filter(s => 
        s.ratings.organization === score || 
        s.ratings.methods === score || 
        s.ratings.practicality === score
      ).length
    }));
  };

  const prepareTrainerData = () => {
    const trainers = ['luiza', 'krzysztof', 'anna', 'tomasz'];
    const metrics = ['knowledge', 'didactics', 'preparation', 'engagement', 'culture'] as const;

    return trainers.map(name => {
      const data: any = { name: name.charAt(0).toUpperCase() + name.slice(1) };
      metrics.forEach(m => {
        const vals = surveys.map(s => (s.trainerRatings as any)[name][m]).filter(v => v !== null);
        data[m] = vals.length ? (vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2) : 0;
      });
      return data;
    });
  };

  const distributionData = prepareScoreDistributionData();
  const trainerData = prepareTrainerData();

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        {/* Score Distribution */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Rozkład Ocen (Główne Kryteria)</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={distributionData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="score" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="count" fill="#f97316" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Trainer Comparison */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Porównanie Trenerów (Średnie)</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trainerData} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                <XAxis type="number" domain={[0, 6]} />
                <YAxis dataKey="name" type="category" />
                <Tooltip />
                <Legend />
                <Bar dataKey="knowledge" fill="#3b82f6" name="Wiedza" />
                <Bar dataKey="didactics" fill="#8b5cf6" name="Dydaktyka" />
                <Bar dataKey="engagement" fill="#ec4899" name="Zaangażowanie" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Radar Chart for Overall Quality */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-bold text-slate-800 mb-6 text-center">Profil Jakości Szkolenia</h3>
        <div className="h-[400px]">
           <ResponsiveContainer width="100%" height="100%">
             <RadarChart cx="50%" cy="50%" outerRadius="80%" data={[
               { subject: 'Organizacja', value: surveys.reduce((acc, s) => acc + (s.ratings.organization || 0), 0) / surveys.length || 0 },
               { subject: 'Metody', value: surveys.reduce((acc, s) => acc + (s.ratings.methods || 0), 0) / surveys.length || 0 },
               { subject: 'Praktyka', value: surveys.reduce((acc, s) => acc + (s.ratings.practicality || 0), 0) / surveys.length || 0 },
               { subject: 'Materiały', value: surveys.reduce((acc, s) => acc + (s.ratings.materialsMerit || 0), 0) / surveys.length || 0 },
               { subject: 'Trenerzy', value: surveys.reduce((acc, s) => acc + (s.trainerRatings.luiza.knowledge || 0), 0) / surveys.length || 0 }
             ]}>
               <PolarGrid />
               <PolarAngleAxis dataKey="subject" />
               <PolarRadiusAxis angle={30} domain={[0, 6]} />
               <Radar name="Ocena" dataKey="value" stroke="#f97316" fill="#f97316" fillOpacity={0.6} />
             </RadarChart>
           </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { AppTab, SurveyRecord } from './types';
import { SurveyUploader } from './components/SurveyUploader';
import { SummaryDashboard } from './components/SummaryDashboard';
import { DetailedTableView } from './components/DetailedTableView';
import { EDADashboard } from './components/EDADashboard';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.UPLOAD);
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);

  const handleDataLoaded = (newSurveys: SurveyRecord[]) => {
    setSurveys(prev => [...prev, ...newSurveys]);
    setActiveTab(AppTab.SUMMARY);
  };

  const clearData = () => {
    if (confirm("Are you sure you want to clear all data?")) {
      setSurveys([]);
      setActiveTab(AppTab.UPLOAD);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Sidebar / Top Nav */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-orange-500 text-white p-2 rounded-lg">
                <i className="fa-solid fa-chart-pie text-lg"></i>
              </div>
              <div>
                <h1 className="text-xl font-extrabold text-slate-800 tracking-tight">QUEST <span className="text-orange-500">Analytics</span></h1>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Training Insights Platform</p>
              </div>
            </div>

            <div className="hidden md:flex gap-1">
              <button 
                onClick={() => setActiveTab(AppTab.UPLOAD)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.UPLOAD ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                <i className="fa-solid fa-upload mr-2"></i> Upload
              </button>
              <button 
                disabled={surveys.length === 0}
                onClick={() => setActiveTab(AppTab.SUMMARY)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.SUMMARY ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50 disabled:opacity-30'}`}
              >
                <i className="fa-solid fa-square-poll-vertical mr-2"></i> Summary
              </button>
              <button 
                disabled={surveys.length === 0}
                onClick={() => setActiveTab(AppTab.TABLE)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.TABLE ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50 disabled:opacity-30'}`}
              >
                <i className="fa-solid fa-table-list mr-2"></i> Table
              </button>
              <button 
                disabled={surveys.length === 0}
                onClick={() => setActiveTab(AppTab.EDA)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.EDA ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50 disabled:opacity-30'}`}
              >
                <i className="fa-solid fa-chart-line mr-2"></i> EDA
              </button>
            </div>

            {surveys.length > 0 && (
              <button 
                onClick={clearData}
                className="text-slate-400 hover:text-red-500 transition-colors p-2"
                title="Clear all data"
              >
                <i className="fa-solid fa-trash-can"></i>
              </button>
            )}
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {surveys.length > 0 && (
          <div className="mb-8 flex items-center justify-between bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
             <div className="flex items-center gap-3">
                <span className="flex h-3 w-3 relative">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                </span>
                <span className="text-sm font-medium text-slate-600">
                  <span className="font-bold text-slate-800">{surveys.length}</span> Surveys processed
                </span>
             </div>
             {activeTab === AppTab.UPLOAD && (
               <button 
                onClick={() => setActiveTab(AppTab.SUMMARY)}
                className="text-xs font-bold text-orange-600 uppercase tracking-wider hover:underline"
               >
                 Back to dashboard →
               </button>
             )}
          </div>
        )}

        {activeTab === AppTab.UPLOAD && (
          <div className="animate-in fade-in duration-500 slide-in-from-bottom-4">
            <SurveyUploader onDataLoaded={handleDataLoaded} />
          </div>
        )}

        {activeTab === AppTab.SUMMARY && (
          <div className="animate-in fade-in duration-500">
            <SummaryDashboard surveys={surveys} />
          </div>
        )}

        {activeTab === AppTab.TABLE && (
          <div className="animate-in fade-in duration-500">
            <DetailedTableView surveys={surveys} />
          </div>
        )}

        {activeTab === AppTab.EDA && (
          <div className="animate-in fade-in duration-500">
            <EDADashboard surveys={surveys} />
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 py-6 text-center text-slate-400 text-xs">
        <p>© {new Date().getFullYear()} Quest Survey Insights. All data processed using Gemini AI.</p>
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { SurveyRecord } from "../types";

const SYSTEM_INSTRUCTION = `
You are an expert OCR and data extraction assistant specialized in Polish training evaluation surveys from "QUEST".
Your task is to analyze documents (images or PDFs) of handwritten/circled surveys and extract data into a structured JSON format.

A survey typically spans two pages or one multi-page document. 
- Content: Title, Date, Place, and numerical ratings (1-6) for organization, methods, practicality, and trainers (Luiza, Krzysztof, Anna, Tomasz).
- Comments: "Szczególnie pozytywnie oceniasz", "Szczególnie negatywnie oceniasz", and suggestions.

CRITICAL RULES:
1. Ratings are numbers from 1 to 6. If a number is circled or marked, that's the rating.
2. Multiple surveys might be present in a single PDF or multiple images. Return an array of all detected surveys.
3. Transcribe handwritten Polish text exactly. Do not summarize unless asked.
4. If a field is empty, use null for numbers or an empty string for text.
5. In "Ocena trenera", extract ratings for all named trainers found in the document.
`;

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    surveys: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          trainingTitle: { type: Type.STRING },
          date: { type: Type.STRING },
          place: { type: Type.STRING },
          ratings: {
            type: Type.OBJECT,
            properties: {
              organization: { type: Type.NUMBER },
              methods: { type: Type.NUMBER },
              practicality: { type: Type.NUMBER },
              materialsClarity: { type: Type.NUMBER },
              materialsMerit: { type: Type.NUMBER }
            }
          },
          trainerRatings: {
            type: Type.OBJECT,
            properties: {
              luiza: { 
                type: Type.OBJECT, 
                properties: { 
                  knowledge: { type: Type.NUMBER }, 
                  didactics: { type: Type.NUMBER }, 
                  preparation: { type: Type.NUMBER }, 
                  engagement: { type: Type.NUMBER }, 
                  culture: { type: Type.NUMBER } 
                } 
              },
              krzysztof: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              anna: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              tomasz: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } }
            }
          },
          comments: {
            type: Type.OBJECT,
            properties: {
              positive: { type: Type.STRING },
              negative: { type: Type.STRING },
              suggestions: { type: Type.STRING }
            }
          }
        }
      }
    }
  }
};

export async function processSurveyFiles(files: { data: string, mimeType: string }[]): Promise<SurveyRecord[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const mediaParts = files.map(file => ({
    inlineData: {
      mimeType: file.mimeType,
      data: file.data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          ...mediaParts,
          { text: "Analyze these evaluation documents and extract all survey data following the provided schema. Each document (image or PDF) might contain one or more surveys." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const result = JSON.parse(response.text || '{"surveys": []}');
    return (result.surveys || []).map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}-${Math.random().toString(36).substr(2, 9)}`
    }));
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

import React, { useState } from 'react';
import { processSurveyFiles } from '../services/geminiService';
import { SurveyRecord } from '../types';

interface SurveyUploaderProps {
  onDataLoaded: (data: SurveyRecord[]) => void;
}

export const SurveyUploader: React.FC<SurveyUploaderProps> = ({ onDataLoaded }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const fileToData = (file: File): Promise<{ data: string, mimeType: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve({
          data: base64,
          mimeType: file.type || 'application/octet-stream'
        });
      };
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    setIsProcessing(true);
    setError(null);
    setProgress(10);

    try {
      const fileList = Array.from(files);
      const processedFiles = await Promise.all(fileList.map(fileToData));

      setProgress(30);

      // Batch processing: Send documents to Gemini
      // Chunks are smaller for PDF as they can be larger in size
      const CHUNK_SIZE = 3;
      const allExtractedSurveys: SurveyRecord[] = [];

      for (let i = 0; i < processedFiles.length; i += CHUNK_SIZE) {
        const chunk = processedFiles.slice(i, i + CHUNK_SIZE);
        const results = await processSurveyFiles(chunk);
        allExtractedSurveys.push(...results);

        const currentProgress = 30 + Math.floor(((i + chunk.length) / processedFiles.length) * 60);
        setProgress(currentProgress);
      }

      onDataLoaded(allExtractedSurveys);
      setProgress(100);
    } catch (err) {
      setError("Nie udało się przetworzyć plików. Upewnij się, że są czytelne i spróbuj ponownie.");
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-8 border border-slate-200">
      <div className="max-w-xl mx-auto text-center">
        <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-file-pdf text-3xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Prześlij ankiety</h2>
        <p className="text-slate-500 mb-8">
          Wybierz zdjęcia (JPG/PNG) lub dokumenty PDF z ankietami QUEST. Nasza AI automatycznie odczyta oceny i pismo ręczne.
        </p>

        {!isProcessing ? (
          <label className="relative group cursor-pointer">
            <div className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 group-hover:border-orange-400 rounded-xl p-10 transition-colors">
              <i className="fa-solid fa-cloud-arrow-up text-4xl text-slate-400 group-hover:text-orange-500 mb-4"></i>
              <span className="text-slate-600 font-medium">Kliknij, aby wybrać pliki</span>
              <span className="text-slate-400 text-sm mt-1">PDF, JPG, PNG (maks. 10MB)</span>
            </div>
            <input 
              type="file" 
              multiple 
              className="hidden" 
              accept="image/*,application/pdf" 
              onChange={handleFileUpload}
            />
          </label>
        ) : (
          <div className="space-y-4">
            <div className="h-4 bg-slate-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-orange-500 transition-all duration-500" 
                style={{ width: `${progress}%` }}
              ></div>
            </div>
            <p className="text-slate-600 font-medium animate-pulse">
              {progress < 30 ? "Inicjalizacja modelu AI..." : "Analizowanie dokumentów i pisma..."}
            </p>
          </div>
        )}

        {error && (
          <div className="mt-6 p-4 bg-red-50 text-red-700 rounded-lg flex items-center gap-3 text-left">
            <i className="fa-solid fa-circle-exclamation flex-shrink-0"></i>
            <span className="text-sm font-medium">{error}</span>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { processSurveyFiles } from '../services/geminiService';
import { SurveyRecord } from '../types';

interface SurveyUploaderProps {
  onDataLoaded: (data: SurveyRecord[]) => void;
}

export const SurveyUploader: React.FC<SurveyUploaderProps> = ({ onDataLoaded }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const fileToData = (file: File): Promise<{ data: string, mimeType: string, name: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve({
          data: base64,
          mimeType: file.type || (file.name.endsWith('.pdf') ? 'application/pdf' : 'application/octet-stream'),
          name: file.name
        });
      };
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    setIsProcessing(true);
    setError(null);
    setProgress(5);

    try {
      const fileList = Array.from(files);
      const processedFiles = await Promise.all(fileList.map(fileToData));

      setProgress(20);

      const allExtractedSurveys: SurveyRecord[] = [];

      // Przetwarzamy pliki jeden po drugim, aby uniknąć limitów rozmiaru zapytania (szczególnie przy PDF)
      for (let i = 0; i < processedFiles.length; i++) {
        const fileObj = processedFiles[i];
        try {
          // Wysyłamy pojedynczy plik (lub małą paczkę zdjęć)
          const results = await processSurveyFiles([fileObj]);
          allExtractedSurveys.push(...results);
        } catch (singleFileErr: any) {
          console.error(`Błąd pliku ${fileObj.name}:`, singleFileErr);
          // Kontynuujemy z następnymi plikami zamiast przerywać całość
        }

        const currentProgress = 20 + Math.floor(((i + 1) / processedFiles.length) * 80);
        setProgress(currentProgress);
      }

      if (allExtractedSurveys.length === 0) {
        throw new Error("Nie udało się wyodrębnić żadnych danych z przesłanych plików.");
      }

      onDataLoaded(allExtractedSurveys);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "Wystąpił nieoczekiwany błąd podczas przetwarzania.");
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-8 border border-slate-200">
      <div className="max-w-xl mx-auto text-center">
        <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-file-pdf text-3xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Prześlij ankiety</h2>
        <p className="text-slate-500 mb-8">
          Wybierz skany lub zdjęcia. Obsługujemy pliki <b>PDF, JPG oraz PNG</b>.
        </p>

        {!isProcessing ? (
          <label className="relative group cursor-pointer">
            <div className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 group-hover:border-orange-400 rounded-xl p-10 transition-colors">
              <i className="fa-solid fa-cloud-arrow-up text-4xl text-slate-400 group-hover:text-orange-500 mb-4"></i>
              <span className="text-slate-600 font-medium">Kliknij, aby wybrać pliki</span>
              <span className="text-slate-400 text-sm mt-1">Akceptowane: .pdf, .jpg, .jpeg, .png</span>
            </div>
            <input 
              type="file" 
              multiple 
              className="hidden" 
              accept=".pdf,image/*" 
              onChange={handleFileUpload}
            />
          </label>
        ) : (
          <div className="space-y-4">
            <div className="h-4 bg-slate-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-orange-500 transition-all duration-500" 
                style={{ width: `${progress}%` }}
              ></div>
            </div>
            <p className="text-slate-600 font-medium animate-pulse">
              Analizowanie dokumentów... ({progress}%)
            </p>
          </div>
        )}

        {error && (
          <div className="mt-6 p-4 bg-red-50 text-red-700 rounded-lg border border-red-100 flex items-start gap-3 text-left">
            <i className="fa-solid fa-circle-exclamation mt-0.5 flex-shrink-0"></i>
            <div>
              <p className="font-bold text-sm">Błąd przetwarzania</p>
              <p className="text-xs mt-1">{error}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { SurveyRecord } from "../types";

const SYSTEM_INSTRUCTION = `
You are an expert OCR and data extraction assistant specialized in Polish training evaluation surveys from "QUEST".
Your task is to analyze documents (images or PDFs) of handwritten/circled surveys and extract data into a structured JSON format.

A document (especially a PDF) can contain:
1. A single survey spanning multiple pages.
2. Many different surveys scanned into one file (one after another).

Your goal is to find ALL surveys within the provided input and return them as an array.

CRITICAL RULES:
- Ratings (1-6): Look for circled numbers or marks.
- Trainers: There are sections for Luiza, Krzysztof, Anna, Tomasz. Extract all their scores.
- Text: Transcribe handwritten Polish comments exactly as they appear.
- Empty fields: Use null for numbers and empty string for text.
- ID generation: Do not provide IDs, the app will handle it.
`;

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    surveys: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          trainingTitle: { type: Type.STRING },
          date: { type: Type.STRING },
          place: { type: Type.STRING },
          ratings: {
            type: Type.OBJECT,
            properties: {
              organization: { type: Type.NUMBER },
              methods: { type: Type.NUMBER },
              practicality: { type: Type.NUMBER },
              materialsClarity: { type: Type.NUMBER },
              materialsMerit: { type: Type.NUMBER }
            }
          },
          trainerRatings: {
            type: Type.OBJECT,
            properties: {
              luiza: { 
                type: Type.OBJECT, 
                properties: { 
                  knowledge: { type: Type.NUMBER }, 
                  didactics: { type: Type.NUMBER }, 
                  preparation: { type: Type.NUMBER }, 
                  engagement: { type: Type.NUMBER }, 
                  culture: { type: Type.NUMBER } 
                } 
              },
              krzysztof: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              anna: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              tomasz: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } }
            }
          },
          comments: {
            type: Type.OBJECT,
            properties: {
              positive: { type: Type.STRING },
              negative: { type: Type.STRING },
              suggestions: { type: Type.STRING }
            }
          }
        }
      }
    }
  }
};

export async function processSurveyFiles(files: { data: string, mimeType: string }[]): Promise<SurveyRecord[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const mediaParts = files.map(file => ({
    inlineData: {
      mimeType: file.mimeType,
      data: file.data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          ...mediaParts,
          { text: "Detect and extract all evaluation surveys from this document. If it's a multi-page PDF, look for surveys on all pages." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("AI returned an empty response.");

    const result = JSON.parse(text);
    return (result.surveys || []).map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}-${Math.random().toString(36).substr(2, 9)}`
    }));
  } catch (error: any) {
    console.error("Gemini API Error Detail:", error);
    if (error.message?.includes("413")) {
      throw new Error("Plik jest zbyt duży dla modelu AI. Spróbuj go podzielić.");
    }
    throw error;
  }
}

import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { SurveyRecord } from '../types';

export const exportToExcel = (surveys: SurveyRecord[]) => {
  // Arkusz 1: Wszystkie dane tabelarycznie
  const flatData = surveys.map(s => ({
    'Szkolenie': s.trainingTitle,
    'Data': s.date,
    'Miejsce': s.place,
    'Organizacja': s.ratings.organization,
    'Metody': s.ratings.methods,
    'Praktyka': s.ratings.practicality,
    'Materiały (Przejrzystość)': s.ratings.materialsClarity,
    'Materiały (Merytoryka)': s.ratings.materialsMerit,
    'Komentarz Pozytywny': s.comments.positive,
    'Komentarz Negatywny': s.comments.negative,
    'Sugestie': s.comments.suggestions,
    'Trener Luiza (Wiedza)': s.trainerRatings.luiza.knowledge,
    'Trener Luiza (Dydaktyka)': s.trainerRatings.luiza.didactics,
    'Trener Krzysztof (Wiedza)': s.trainerRatings.krzysztof.knowledge,
    'Trener Krzysztof (Dydaktyka)': s.trainerRatings.krzysztof.didactics,
    'Trener Anna (Wiedza)': s.trainerRatings.anna.knowledge,
    'Trener Anna (Dydaktyka)': s.trainerRatings.anna.didactics,
    'Trener Tomasz (Wiedza)': s.trainerRatings.tomasz.knowledge,
    'Trener Tomasz (Dydaktyka)': s.trainerRatings.tomasz.didactics,
  }));

  const wb = XLSX.utils.book_new();
  const wsDetails = XLSX.utils.json_to_sheet(flatData);
  XLSX.utils.book_append_sheet(wb, wsDetails, "Szczegóły Ankiet");

  // Arkusz 2: Podsumowanie (Średnie)
  const avg = (arr: (number | null)[]) => {
    const valid = arr.filter(v => v !== null) as number[];
    return valid.length ? (valid.reduce((a, b) => a + b, 0) / valid.length).toFixed(2) : 0;
  };

  const summaryData = [
    ['Kategoria', 'Średnia Ocena'],
    ['Organizacja', avg(surveys.map(s => s.ratings.organization))],
    ['Metody', avg(surveys.map(s => s.ratings.methods))],
    ['Praktyka', avg(surveys.map(s => s.ratings.practicality))],
    ['Materiały (Przejrzystość)', avg(surveys.map(s => s.ratings.materialsClarity))],
    ['Materiały (Merytoryka)', avg(surveys.map(s => s.ratings.materialsMerit))],
  ];

  const wsSummary = XLSX.utils.aoa_to_sheet(summaryData);
  XLSX.utils.book_append_sheet(wb, wsSummary, "Podsumowanie");

  XLSX.writeFile(wb, `Raport_Quest_${new Date().toISOString().slice(0, 10)}.xlsx`);
};

export const exportToPDF = (surveys: SurveyRecord[]) => {
  const doc = new jsPDF() as any;
  const timestamp = new Date().toLocaleDateString('pl-PL');

  // Nagłówek
  doc.setFontSize(20);
  doc.setTextColor(249, 115, 22); // Orange 500
  doc.text('QUEST Analytics - Raport Szkoleniowy', 14, 22);

  doc.setFontSize(10);
  doc.setTextColor(100);
  doc.text(`Data wygenerowania: ${timestamp}`, 14, 30);
  doc.text(`Liczba przeanalizowanych ankiet: ${surveys.length}`, 14, 35);

  // Tabela ze średnimi
  const avg = (arr: (number | null)[]) => {
    const valid = arr.filter(v => v !== null) as number[];
    return valid.length ? (valid.reduce((a, b) => a + b, 0) / valid.length).toFixed(2) : 0;
  };

  doc.autoTable({
    startY: 45,
    head: [['Kategoria', 'Średnia Ocena']],
    body: [
      ['Organizacja', avg(surveys.map(s => s.ratings.organization))],
      ['Metody', avg(surveys.map(s => s.ratings.methods))],
      ['Praktyka', avg(surveys.map(s => s.ratings.practicality))],
      ['Materiały (Przejrzystość)', avg(surveys.map(s => s.ratings.materialsClarity))],
      ['Materiały (Merytoryka)', avg(surveys.map(s => s.ratings.materialsMerit))],
    ],
    theme: 'striped',
    headStyles: { fillColor: [249, 115, 22] }
  });

  // Komentarze
  let currentY = (doc as any).lastAutoTable.finalY + 15;
  doc.setFontSize(14);
  doc.setTextColor(0);
  doc.text('Wybrane Komentarze Uczestników:', 14, currentY);

  const comments = surveys
    .map(s => s.comments.positive || s.comments.suggestions)
    .filter(c => c && c.length > 5)
    .slice(0, 15);

  doc.setFontSize(9);
  doc.setTextColor(60);
  comments.forEach((comment, index) => {
    currentY += 8;
    if (currentY > 280) {
      doc.addPage();
      currentY = 20;
    }
    const splitText = doc.splitTextToSize(`• ${comment}`, 180);
    doc.text(splitText, 14, currentY);
    currentY += (splitText.length - 1) * 4;
  });

  doc.save(`Raport_Quest_${new Date().toISOString().slice(0, 10)}.pdf`);
};

