import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { SurveyRecord } from '../types';

// Helper to calculate averages safely
const avg = (arr: (number | null)[]) => {
  const valid = arr.filter(v => v !== null && !isNaN(v)) as number[];
  return valid.length ? parseFloat((valid.reduce((a, b) => a + b, 0) / valid.length).toFixed(2)) : 0;
};

export const exportToExcel = (surveys: SurveyRecord[]) => {
  const wb = XLSX.utils.book_new();

  // 1. RAW DATA SHEET
  const flatData = surveys.map(s => ({
    'Szkolenie': s.trainingTitle,
    'Data': s.date,
    'Miejsce': s.place,
    'Organizacja': s.ratings.organization,
    'Metody': s.ratings.methods,
    'Praktyka': s.ratings.practicality,
    'Przejrzystość Mat.': s.ratings.materialsClarity,
    'Merytoryka Mat.': s.ratings.materialsMerit,
    'Komentarz (+)': s.comments.positive,
    'Komentarz (-)': s.comments.negative,
    'Sugestie': s.comments.suggestions,
    'LUIZA: Wiedza': s.trainerRatings.luiza.knowledge,
    'LUIZA: Dydaktyka': s.trainerRatings.luiza.didactics,
    'LUIZA: Kultura': s.trainerRatings.luiza.culture,
    'KRZYSZTOF: Wiedza': s.trainerRatings.krzysztof.knowledge,
    'KRZYSZTOF: Dydaktyka': s.trainerRatings.krzysztof.didactics,
    'ANNA: Wiedza': s.trainerRatings.anna.knowledge,
    'ANNA: Dydaktyka': s.trainerRatings.anna.didactics,
    'TOMASZ: Wiedza': s.trainerRatings.tomasz.knowledge,
    'TOMASZ: Dydaktyka': s.trainerRatings.tomasz.didactics,
  }));
  const wsDetails = XLSX.utils.json_to_sheet(flatData);
  XLSX.utils.book_append_sheet(wb, wsDetails, "Dane Szczegółowe");

  // 2. GENERAL SUMMARY SHEET
  const summaryData = [
    ['Kategoria', 'Średnia Ocena', 'Liczba Odpowiedzi'],
    ['Organizacja', avg(surveys.map(s => s.ratings.organization)), surveys.filter(s => s.ratings.organization).length],
    ['Metody', avg(surveys.map(s => s.ratings.methods)), surveys.filter(s => s.ratings.methods).length],
    ['Praktyka', avg(surveys.map(s => s.ratings.practicality)), surveys.filter(s => s.ratings.practicality).length],
    ['Materiały (Przejrzystość)', avg(surveys.map(s => s.ratings.materialsClarity)), surveys.filter(s => s.ratings.materialsClarity).length],
    ['Materiały (Merytoryka)', avg(surveys.map(s => s.ratings.materialsMerit)), surveys.filter(s => s.ratings.materialsMerit).length],
  ];
  const wsSummary = XLSX.utils.aoa_to_sheet(summaryData);
  XLSX.utils.book_append_sheet(wb, wsSummary, "Podsumowanie");

  // 3. TRAINERS EDA SHEET
  const trainers = ['luiza', 'krzysztof', 'anna', 'tomasz'];
  const trainerData = [
    ['Trener', 'Wiedza', 'Dydaktyka', 'Przygotowanie', 'Zaangażowanie', 'Kultura'],
    ...trainers.map(t => [
      t.toUpperCase(),
      avg(surveys.map(s => (s.trainerRatings as any)[t].knowledge)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].didactics)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].preparation)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].engagement)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].culture)),
    ])
  ];
  const wsTrainers = XLSX.utils.aoa_to_sheet(trainerData);
  XLSX.utils.book_append_sheet(wb, wsTrainers, "Analiza Trenerów");

  // 4. SCORE DISTRIBUTION SHEET
  const scores = [1, 2, 3, 4, 5, 6];
  const distData = [
    ['Ocena', 'Główne Kryteria (suma wystąpień)'],
    ...scores.map(score => [
      score,
      surveys.filter(s => 
        s.ratings.organization === score || 
        s.ratings.methods === score || 
        s.ratings.practicality === score
      ).length
    ])
  ];
  const wsDist = XLSX.utils.aoa_to_sheet(distData);
  XLSX.utils.book_append_sheet(wb, wsDist, "Rozkład Ocen");

  XLSX.writeFile(wb, `Raport_Kompletny_Quest_${new Date().toISOString().slice(0, 10)}.xlsx`);
};

export const exportToPDF = (surveys: SurveyRecord[]) => {
  // Use constructor with specific settings for better support
  const doc = new jsPDF({
    orientation: 'p',
    unit: 'mm',
    format: 'a4',
    putOnlyUsedFonts: true
  }) as any;

  const timestamp = new Date().toLocaleDateString('pl-PL');

  // --- PAGE 1: HEADER & GENERAL SUMMARY ---
  doc.setFontSize(22);
  doc.setTextColor(249, 115, 22); // Orange 500
  doc.text('QUEST Analytics', 14, 20);

  doc.setFontSize(14);
  doc.setTextColor(51, 65, 85); // Slate 700
  doc.text('Raport Zbiorczy z Ankiet Szkoleniowych', 14, 28);

  doc.setFontSize(9);
  doc.setTextColor(100);
  doc.text(`Wygenerowano: ${timestamp} | Liczba ankiet: ${surveys.length}`, 14, 35);
  doc.line(14, 38, 196, 38);

  doc.setFontSize(12);
  doc.setTextColor(0);
  doc.text('1. Średnie Oceny Główne', 14, 48);

  doc.autoTable({
    startY: 52,
    head: [['Kategoria', 'Średnia (1-6)', 'N (odpowiedzi)']],
    body: [
      ['Organizacja', avg(surveys.map(s => s.ratings.organization)), surveys.filter(s => s.ratings.organization).length],
      ['Metody', avg(surveys.map(s => s.ratings.methods)), surveys.filter(s => s.ratings.methods).length],
      ['Praktyka i Narzędzia', avg(surveys.map(s => s.ratings.practicality)), surveys.filter(s => s.ratings.practicality).length],
      ['Materiały (Przejrzystość)', avg(surveys.map(s => s.ratings.materialsClarity)), surveys.filter(s => s.ratings.materialsClarity).length],
      ['Materiały (Merytoryka)', avg(surveys.map(s => s.ratings.materialsMerit)), surveys.filter(s => s.ratings.materialsMerit).length],
    ],
    theme: 'grid',
    headStyles: { fillColor: [249, 115, 22] },
    styles: { fontSize: 10 }
  });

  doc.text('2. Ranking i Analiza Trenerów', 14, (doc as any).lastAutoTable.finalY + 15);

  const trainers = ['luiza', 'krzysztof', 'anna', 'tomasz'];
  doc.autoTable({
    startY: (doc as any).lastAutoTable.finalY + 20,
    head: [['Trener', 'Wiedza', 'Dydaktyka', 'Kultura', 'Śr. Ogólna']],
    body: trainers.map(t => {
      const w = avg(surveys.map(s => (s.trainerRatings as any)[t].knowledge));
      const d = avg(surveys.map(s => (s.trainerRatings as any)[t].didactics));
      const k = avg(surveys.map(s => (s.trainerRatings as any)[t].culture));
      const total = avg([w, d, k]);
      return [t.toUpperCase(), w || '-', d || '-', k || '-', total || '-'];
    }),
    theme: 'striped',
    headStyles: { fillColor: [51, 65, 85] },
    styles: { fontSize: 9 }
  });

  // --- PAGE 2: COMMENTS ---
  doc.addPage();
  doc.setFontSize(14);
  doc.text('3. Głos Uczestników (Komentarze)', 14, 20);

  const posComments = surveys.map(s => s.comments.positive).filter(c => c && c.length > 2);
  const negComments = surveys.map(s => s.comments.negative).filter(c => c && c.length > 2);
  const suggestions = surveys.map(s => s.comments.suggestions).filter(c => c && c.length > 2);

  let y = 30;

  if (posComments.length) {
    doc.setFontSize(11);
    doc.setTextColor(22, 163, 74); // Green 600
    doc.text('Mocne strony:', 14, y);
    y += 5;
    doc.setFontSize(9);
    doc.setTextColor(60);
    posComments.slice(0, 10).forEach(c => {
      const lines = doc.splitTextToSize(`• ${c}`, 180);
      doc.text(lines, 14, y);
      y += (lines.length * 4) + 2;
    });
  }

  y += 5;
  if (suggestions.length) {
    doc.setFontSize(11);
    doc.setTextColor(249, 115, 22);
    doc.text('Sugestie i kierunki rozwoju:', 14, y);
    y += 5;
    doc.setFontSize(9);
    doc.setTextColor(60);
    suggestions.slice(0, 10).forEach(c => {
      const lines = doc.splitTextToSize(`• ${c}`, 180);
      doc.text(lines, 14, y);
      y += (lines.length * 4) + 2;
    });
  }

  // --- PAGE 3+: DETAILED TABLE ---
  doc.addPage();
  doc.setFontSize(14);
  doc.setTextColor(0);
  doc.text('4. Zestawienie Tabelaryczne (Wszystkie odpowiedzi)', 14, 20);

  doc.autoTable({
    startY: 25,
    head: [['ID', 'Tytuł Szkolenia', 'Data/Miejsce', 'Org', 'Met', 'Prac']],
    body: surveys.map((s, idx) => [
      idx + 1,
      s.trainingTitle || '-',
      `${s.date || ''} ${s.place || ''}`,
      s.ratings.organization || '-',
      s.ratings.methods || '-',
      s.ratings.practicality || '-'
    ]),
    theme: 'grid',
    styles: { fontSize: 8 },
    headStyles: { fillColor: [249, 115, 22] }
  });

  doc.save(`Raport_Quest_Full_${new Date().toISOString().slice(0, 10)}.pdf`);
};

