                     <span className={`inline-block w-8 py-1 rounded font-bold text-xs ${getColor(s.ratings.organization)}`}>{s.ratings.organization || '-'}</span>
                  </td>
                  <td className="px-2 py-4 text-center">
                     <span className={`inline-block w-8 py-1 rounded font-bold text-xs ${getColor(s.ratings.methods)}`}>{s.ratings.methods || '-'}</span>
                  </td>
                  <td className="px-2 py-4 text-center">
                     <span className={`inline-block w-8 py-1 rounded font-bold text-xs ${getColor(s.ratings.practicality)}`}>{s.ratings.practicality || '-'}</span>
                  </td>
                  <td className="px-2 py-4 text-center">
                     <span className={`inline-block w-8 py-1 rounded font-bold text-xs ${getColor(s.ratings.materialsClarity)}`}>{s.ratings.materialsClarity || '-'}</span>
                  </td>
                  <td className="px-2 py-4 text-center">
                     <span className={`inline-block w-8 py-1 rounded font-bold text-xs ${getColor(s.ratings.materialsMerit)}`}>{s.ratings.materialsMerit || '-'}</span>
                  </td>
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-2">
                      <div className="w-12 h-2 bg-slate-100 rounded-full overflow-hidden">
                        <div className="h-full bg-orange-400" style={{ width: trainerAvg !== '-' ? `${(parseFloat(trainerAvg)/6)*100}%` : '0%' }}></div>
                      </div>
                      <span className="text-xs font-bold text-slate-600">{trainerAvg}</span>
                    </div>
                  </td>
                  <td className="px-4 py-4">
                    <p className="text-xs text-slate-500 line-clamp-2 italic max-w-xs group-hover:text-slate-800 transition-colors">
                      {s.comments.positive || s.comments.suggestions || 'Brak uwag'}
                    </p>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

function getColor(val: number | null): string {
  if (!val) return 'bg-slate-50 text-slate-300';
  if (val >= 5) return 'bg-green-50 text-green-700';
  if (val >= 4) return 'bg-blue-50 text-blue-700';
  if (val >= 3) return 'bg-yellow-50 text-yellow-700';
  return 'bg-red-50 text-red-700';
}

