const avg = (arr: (number | null)[]) => {
  const valid = arr.filter(v => v !== null && !isNaN(v)) as number[];
  return valid.length ? parseFloat((valid.reduce((a, b) => a + b, 0) / valid.length).toFixed(2)) : 0;
