export const exportToExcel = (surveys: SurveyRecord[]) => {
  const wb = XLSX.utils.book_new();

  // 1. RAW DATA SHEET
  const flatData = surveys.map(s => ({
    'Szkolenie': s.trainingTitle,
    'Data': s.date,
    'Miejsce': s.place,
    'Organizacja': s.ratings.organization,
    'Metody': s.ratings.methods,
    'Praktyka': s.ratings.practicality,
    'Przejrzystość Mat.': s.ratings.materialsClarity,
    'Merytoryka Mat.': s.ratings.materialsMerit,
    'Komentarz (+)': s.comments.positive,
    'Komentarz (-)': s.comments.negative,
    'Sugestie': s.comments.suggestions,
    'LUIZA: Merytoryka': s.trainerRatings.luiza.knowledge,
    'LUIZA: Dydaktyka': s.trainerRatings.luiza.didactics,
    'LUIZA: Przygotowanie': s.trainerRatings.luiza.preparation,
    'LUIZA: Komunikacja': s.trainerRatings.luiza.engagement,
    'LUIZA: Kultura': s.trainerRatings.luiza.culture,
    'KRZYSZTOF: Merytoryka': s.trainerRatings.krzysztof.knowledge,
    'KRZYSZTOF: Dydaktyka': s.trainerRatings.krzysztof.didactics,
    'KRZYSZTOF: Przygotowanie': s.trainerRatings.krzysztof.preparation,
    'KRZYSZTOF: Komunikacja': s.trainerRatings.krzysztof.engagement,
