    ['Kategoria', 'Średnia Ocena', 'Liczba Odpowiedzi'],
    ['Organizacja', avg(surveys.map(s => s.ratings.organization)), surveys.filter(s => s.ratings.organization).length],
    ['Metody', avg(surveys.map(s => s.ratings.methods)), surveys.filter(s => s.ratings.methods).length],
    ['Praktyka', avg(surveys.map(s => s.ratings.practicality)), surveys.filter(s => s.ratings.practicality).length],
    ['Materiały (Przejrzystość)', avg(surveys.map(s => s.ratings.materialsClarity)), surveys.filter(s => s.ratings.materialsClarity).length],
    ['Materiały (Merytoryka)', avg(surveys.map(s => s.ratings.materialsMerit)), surveys.filter(s => s.ratings.materialsMerit).length],
  ];
  const wsSummary = XLSX.utils.aoa_to_sheet(summaryData);
  XLSX.utils.book_append_sheet(wb, wsSummary, "Podsumowanie");

  // 3. TRAINERS EDA SHEET
  const trainers = ['luiza', 'krzysztof', 'anna', 'tomasz'];
  const trainerData = [
    ['Trener', '1. Merytoryka', '2. Dydaktyka', '3. Przygotowanie', '4. Komunikacja', '5. Kultura'],
    ...trainers.map(t => [
      t.toUpperCase(),
      avg(surveys.map(s => (s.trainerRatings as any)[t].knowledge)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].didactics)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].preparation)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].engagement)),
      avg(surveys.map(s => (s.trainerRatings as any)[t].culture)),
    ])
  ];
  const wsTrainers = XLSX.utils.aoa_to_sheet(trainerData);
  XLSX.utils.book_append_sheet(wb, wsTrainers, "Analiza Trenerów");

  XLSX.writeFile(wb, `Raport_Kompletny_Quest_${new Date().toISOString().slice(0, 10)}.xlsx`);
};

export const exportToPDF = (surveys: SurveyRecord[]) => {
  const doc = new jsPDF({
    orientation: 'p',
    unit: 'mm',
    format: 'a4',
    putOnlyUsedFonts: true
  }) as any;

  const timestamp = new Date().toLocaleDateString('pl-PL');

  // --- PAGE 1: HEADER & GENERAL SUMMARY ---
  doc.setFontSize(22);
  doc.setTextColor(249, 115, 22);
  doc.text('QUEST Analytics', 14, 20);

  doc.setFontSize(14);
  doc.setTextColor(51, 65, 85);
  doc.text('Raport Zbiorczy z Ankiet Szkoleniowych', 14, 28);

  doc.setFontSize(9);
  doc.setTextColor(100);
  doc.text(`Wygenerowano: ${timestamp} | Liczba ankiet: ${surveys.length}`, 14, 35);
  doc.line(14, 38, 196, 38);

  doc.setFontSize(12);
  doc.setTextColor(0);
  doc.text('1. Średnie Oceny Główne', 14, 48);

  doc.autoTable({
    startY: 52,
    head: [['Kategoria', 'Średnia (1-6)', 'N']],
    body: [
      ['Organizacja', avg(surveys.map(s => s.ratings.organization)), surveys.filter(s => s.ratings.organization).length],
      ['Metody', avg(surveys.map(s => s.ratings.methods)), surveys.filter(s => s.ratings.methods).length],
      ['Praktyka i Narzędzia', avg(surveys.map(s => s.ratings.practicality)), surveys.filter(s => s.ratings.practicality).length],
      ['Materiały (Przejrzystość)', avg(surveys.map(s => s.ratings.materialsClarity)), surveys.filter(s => s.ratings.materialsClarity).length],
      ['Materiały (Merytoryka)', avg(surveys.map(s => s.ratings.materialsMerit)), surveys.filter(s => s.ratings.materialsMerit).length],
    ],
    theme: 'grid',
    headStyles: { fillColor: [249, 115, 22] },
    styles: { fontSize: 10 }
  });

  doc.text('2. Szczegółowa Analiza Trenerów', 14, (doc as any).lastAutoTable.finalY + 15);

  const trainers = ['luiza', 'krzysztof', 'anna', 'tomasz'];
  doc.autoTable({
    startY: (doc as any).lastAutoTable.finalY + 20,
    head: [['Trener', 'Meryt.', 'Dydakt.', 'Przygot.', 'Komun.', 'Kultura']],
    body: trainers.map(t => {
      const row = (surveys[0].trainerRatings as any)[t];
      if (!row) return null;
      return [
        t.toUpperCase(),
        avg(surveys.map(s => (s.trainerRatings as any)[t].knowledge)) || '-',
        avg(surveys.map(s => (s.trainerRatings as any)[t].didactics)) || '-',
        avg(surveys.map(s => (s.trainerRatings as any)[t].preparation)) || '-',
        avg(surveys.map(s => (s.trainerRatings as any)[t].engagement)) || '-',
        avg(surveys.map(s => (s.trainerRatings as any)[t].culture)) || '-'
      ];
    }).filter(Boolean),
    theme: 'striped',
    headStyles: { fillColor: [51, 65, 85] },
    styles: { fontSize: 8 }
  });

  // --- PAGE 2: COMMENTS ---
  doc.addPage();
  doc.setFontSize(14);
  doc.text('3. Głos Uczestników (Komentarze)', 14, 20);

  const posComments = surveys.map(s => s.comments.positive).filter(c => c && c.length > 2);
  const suggestions = surveys.map(s => s.comments.suggestions).filter(c => c && c.length > 2);

  let y = 30;
  if (posComments.length) {
    doc.setFontSize(11);
    doc.setTextColor(22, 163, 74);
    doc.text('Mocne strony:', 14, y);
    y += 5;
    doc.setFontSize(9);
    doc.setTextColor(60);
    posComments.slice(0, 15).forEach(c => {
      const lines = doc.splitTextToSize(`• ${c}`, 180);
      if (y > 270) { doc.addPage(); y = 20; }
      doc.text(lines, 14, y);
      y += (lines.length * 4) + 2;
    });
  }

  doc.save(`Raport_Quest_Full_${new Date().toISOString().slice(0, 10)}.pdf`);
};

import React, { useState, useEffect, useMemo } from 'react';
import { AppTab, SurveyRecord } from './types';
import { SurveyUploader } from './components/SurveyUploader';
import { SummaryDashboard } from './components/SummaryDashboard';
import { DetailedTableView } from './components/DetailedTableView';
import { EDADashboard } from './components/EDADashboard';
import { exportToExcel, exportToPDF, exportToPPTX } from './utils/exportUtils';

const STORAGE_KEY = 'quest_survey_data';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.UPLOAD);
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);

  // Filtry
  const [selectedYear, setSelectedYear] = useState<string>('all');
  const [selectedQuarter, setSelectedQuarter] = useState<string>('all');
  const [selectedTraining, setSelectedTraining] = useState<string>('all');

  // Ładowanie danych z localStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setSurveys(JSON.parse(saved));
      } catch (e) {
        console.error("Błąd ładowania danych z storage", e);
      }
    }
  }, []);

  // Zapisywanie danych do localStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
  }, [surveys]);

  const handleDataLoaded = (newSurveys: SurveyRecord[], fileName: string) => {
    const existingFileNames = surveys.map(s => s.fileName);

    if (existingFileNames.includes(fileName)) {
      if (confirm(`Dane z pliku "${fileName}" już istnieją w systemie. Czy chcesz je zaktualizować (nadpisać)?`)) {
        setSurveys(prev => [
          ...prev.filter(s => s.fileName !== fileName),
          ...newSurveys.map(s => ({ ...s, fileName }))
        ]);
        alert("Dane zostały zaktualizowane.");
      } else {
        return; // Ignorujemy
      }
    } else {
      setSurveys(prev => [...prev, ...newSurveys.map(s => ({ ...s, fileName }))]);
    }

    setActiveTab(AppTab.SUMMARY);
  };

  const getQuarter = (dateStr: string) => {
    if (!dateStr) return null;
    const parts = dateStr.split('.');
    if (parts.length < 2) return null;
    const month = parseInt(parts[1], 10);
    if (month >= 1 && month <= 3) return 'I';
    if (month >= 4 && month <= 6) return 'II';
    if (month >= 7 && month <= 9) return 'III';
    if (month >= 10 && month <= 12) return 'IV';
    return null;
  };

  const getYear = (dateStr: string) => {
    if (!dateStr) return null;
    const parts = dateStr.split('.');
    return parts[parts.length - 1];
  };

  const filteredSurveys = useMemo(() => {
    return surveys.filter(s => {
      const year = getYear(s.date);
      const quarter = getQuarter(s.date);

      const matchYear = selectedYear === 'all' || year === selectedYear;
      const matchQuarter = selectedQuarter === 'all' || quarter === selectedQuarter;
      const matchTraining = selectedTraining === 'all' || s.trainingTitle === selectedTraining;

      return matchYear && matchQuarter && matchTraining;
    });
  }, [surveys, selectedYear, selectedQuarter, selectedTraining]);

  const uniqueTrainings = useMemo(() => {
    return Array.from(new Set(surveys.map(s => s.trainingTitle))).filter(Boolean);
  }, [surveys]);

  const clearData = () => {
    if (confirm("Czy na pewno chcesz usunąć WSZYSTKIE zgromadzone dane z bazy?")) {
      setSurveys([]);
      localStorage.removeItem(STORAGE_KEY);
      setActiveTab(AppTab.UPLOAD);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-orange-500 text-white p-2 rounded-lg shadow-sm">
                <i className="fa-solid fa-chart-pie text-lg"></i>
              </div>
              <div>
                <h1 className="text-xl font-extrabold text-slate-800 tracking-tight">QUEST <span className="text-orange-500">Analytics</span></h1>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Historyczny Tracking Wyników</p>
              </div>
            </div>

            <div className="hidden md:flex gap-1">
              <button 
                onClick={() => setActiveTab(AppTab.UPLOAD)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.UPLOAD ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                <i className="fa-solid fa-plus-circle mr-2"></i> Nowe Dane
              </button>
              <button 
                disabled={surveys.length === 0}
                onClick={() => setActiveTab(AppTab.SUMMARY)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.SUMMARY ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50 disabled:opacity-30'}`}
              >
                <i className="fa-solid fa-gauge-high mr-2"></i> Dashboard
              </button>
              <button 
                disabled={surveys.length === 0}
                onClick={() => setActiveTab(AppTab.TABLE)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.TABLE ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50 disabled:opacity-30'}`}
              >
                <i className="fa-solid fa-list-check mr-2"></i> Dane
              </button>
              <button 
                disabled={surveys.length === 0}
                onClick={() => setActiveTab(AppTab.EDA)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.EDA ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50 disabled:opacity-30'}`}
              >
                <i className="fa-solid fa-chart-line mr-2"></i> Analiza
              </button>
            </div>

            <div className="flex items-center gap-2">
              {surveys.length > 0 && (
                <div className="flex items-center gap-1">
                  <button onClick={() => exportToExcel(filteredSurveys)} className="p-2 text-green-600 hover:bg-green-50 rounded-lg border border-green-100" title="Excel"><i className="fa-solid fa-file-excel"></i></button>
                  <button onClick={() => exportToPDF(filteredSurveys)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg border border-red-100" title="PDF"><i className="fa-solid fa-file-pdf"></i></button>
                  <button onClick={() => exportToPPTX(filteredSurveys)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg border border-blue-100" title="PowerPoint"><i className="fa-solid fa-file-powerpoint"></i></button>
                  <div className="w-px h-6 bg-slate-200 mx-1"></div>
                  <button onClick={clearData} className="text-slate-300 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash"></i></button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* Pasek Filtrów */}
      {surveys.length > 0 && (
        <div className="bg-slate-800 text-white border-b border-slate-700 py-3 shadow-inner">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-wrap items-center gap-6">
            <div className="flex items-center gap-2">
              <label className="text-[10px] uppercase font-bold text-slate-400">Rok:</label>
              <select 
                value={selectedYear} 
                onChange={(e) => setSelectedYear(e.target.value)}
                className="bg-slate-700 border border-slate-600 rounded px-2 py-1 text-xs focus:ring-1 focus:ring-orange-500 outline-none"
              >
                <option value="all">Wszystkie lata</option>
                <option value="2024">2024</option>
                <option value="2025">2025</option>
                <option value="2026">2026</option>
              </select>
            </div>

            <div className="flex items-center gap-2">
              <label className="text-[10px] uppercase font-bold text-slate-400">Kwartał:</label>
              <div className="flex gap-1">
                {['all', 'I', 'II', 'III', 'IV'].map(q => (
                  <button 
                    key={q} 
                    onClick={() => setSelectedQuarter(q)}
                    className={`px-3 py-1 text-[10px] font-bold rounded transition-colors ${selectedQuarter === q ? 'bg-orange-500 text-white' : 'bg-slate-700 text-slate-300 hover:bg-slate-600'}`}
                  >
                    {q === 'all' ? 'WSZYSTKIE' : q}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex items-center gap-2 flex-1">
              <label className="text-[10px] uppercase font-bold text-slate-400">Szkolenie:</label>
              <select 
                value={selectedTraining} 
                onChange={(e) => setSelectedTraining(e.target.value)}
                className="bg-slate-700 border border-slate-600 rounded px-2 py-1 text-xs flex-1 max-w-md focus:ring-1 focus:ring-orange-500 outline-none"
              >
                <option value="all">Wszystkie warsztaty</option>
                {uniqueTrainings.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            <div className="text-[10px] bg-slate-900 px-3 py-1 rounded-full text-slate-400 border border-slate-700">
              Wyniki dla: <span className="text-orange-400 font-bold">{filteredSurveys.length}</span> / {surveys.length} ankiet
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === AppTab.UPLOAD && (
          <div className="animate-in fade-in duration-500 slide-in-from-bottom-4">
            <SurveyUploader onDataLoaded={(data) => handleDataLoaded(data, (document.querySelector('input[type="file"]') as HTMLInputElement)?.files?.[0]?.name || 'scan.pdf')} />
          </div>
        )}

        {filteredSurveys.length > 0 ? (
          <>
            {activeTab === AppTab.SUMMARY && <SummaryDashboard surveys={filteredSurveys} />}
            {activeTab === AppTab.TABLE && <DetailedTableView surveys={filteredSurveys} />}
            {activeTab === AppTab.EDA && <EDADashboard surveys={filteredSurveys} />}
          </>
        ) : surveys.length > 0 && activeTab !== AppTab.UPLOAD ? (
          <div className="bg-white p-20 rounded-2xl border-2 border-dashed border-slate-200 text-center">
            <i className="fa-solid fa-filter-circle-xmark text-5xl text-slate-200 mb-4"></i>
            <h3 className="text-xl font-bold text-slate-800">Brak wyników dla tych filtrów</h3>
            <p className="text-slate-500 mt-2">Zmień rok, kwartał lub wybierz inne szkolenie.</p>
            <button onClick={() => {setSelectedYear('all'); setSelectedQuarter('all'); setSelectedTraining('all');}} className="mt-6 text-orange-600 font-bold hover:underline">Resetuj filtry</button>
          </div>
        ) : null}
      </main>

      <footer className="bg-white border-t border-slate-200 py-6 text-center text-slate-400 text-[10px] uppercase tracking-widest font-bold">
        <p>© {new Date().getFullYear()} Quest Survey Insights. Baza ankiet zabezpieczona lokalnie.</p>
      </footer>
    </div>
  );
};

export default App;

import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import pptxgen from 'pptxgenjs';
import { SurveyRecord } from '../types';

const avg = (arr: (number | null)[]) => {
  const valid = arr.filter(v => v !== null && !isNaN(v)) as number[];
  return valid.length ? parseFloat((valid.reduce((a, b) => a + b, 0) / valid.length).toFixed(2)) : 0;
};

export const exportToExcel = (surveys: SurveyRecord[]) => {
  const wb = XLSX.utils.book_new();
  const flatData = surveys.map(s => ({
    'ID': s.id,
    'Plik': s.fileName,
    'Szkolenie': s.trainingTitle,
    'Data': s.date,
    'Miejsce': s.place,
    'Org': s.ratings.organization,
    'Metody': s.ratings.methods,
    'Praktyka': s.ratings.practicality,
    'LUIZA: Meryt.': s.trainerRatings.luiza.knowledge,
    'LUIZA: Komun.': s.trainerRatings.luiza.engagement,
    'KRZYSZTOF: Meryt.': s.trainerRatings.krzysztof.knowledge,
    'KRZYSZTOF: Komun.': s.trainerRatings.krzysztof.engagement,
    'Plusy': s.comments.positive,
    'Sugestie': s.comments.suggestions
  }));
  const ws = XLSX.utils.json_to_sheet(flatData);
  XLSX.utils.book_append_sheet(wb, ws, "Filtrowane Dane");
  XLSX.writeFile(wb, `Quest_Export_${new Date().toISOString().slice(0,10)}.xlsx`);
};

export const exportToPDF = (surveys: SurveyRecord[]) => {
  const doc = new jsPDF() as any;
  doc.setFontSize(18);
  doc.text('Quest Survey Analytics - Raport', 14, 20);
  doc.setFontSize(10);
  doc.text(`Liczba ankiet w raporcie: ${surveys.length}`, 14, 30);

  doc.autoTable({
    startY: 40,
    head: [['Szkolenie', 'Data', 'Org', 'Met', 'Meryt. Śr']],
    body: surveys.map(s => [
      s.trainingTitle, 
