export const exportToPPTX = (surveys: SurveyRecord[]) => {
  const pres = new pptxgen();

  // Slide 1: Title
  const slide1 = pres.addSlide();
  slide1.background = { fill: 'F8FAFC' };
  slide1.addText('QUEST ANALYTICS', { x: 0.5, y: 1.5, w: '90%', fontSize: 44, color: 'f97316', bold: true, align: 'center' });
  slide1.addText('Podsumowanie Wyników Ankiet Szkoleniowych', { x: 0.5, y: 2.5, w: '90%', fontSize: 24, color: '1e293b', align: 'center' });
  slide1.addText(`Liczba przeanalizowanych ankiet: ${surveys.length}`, { x: 0.5, y: 4, w: '90%', fontSize: 14, color: '64748b', align: 'center' });

  // Slide 2: Main Ratings
  const slide2 = pres.addSlide();
  slide2.addText('Średnie Oceny Główne', { x: 0.5, y: 0.5, fontSize: 28, color: 'f97316', bold: true });

  const mainMetrics = [
    ['Kategoria', 'Średnia (1-6)'],
    ['Organizacja', avg(surveys.map(s => s.ratings.organization)).toString()],
    ['Metody', avg(surveys.map(s => s.ratings.methods)).toString()],
    ['Praktyka', avg(surveys.map(s => s.ratings.practicality)).toString()],
    ['Przejrzystość materiałów', avg(surveys.map(s => s.ratings.materialsClarity)).toString()],
    ['Merytoryka materiałów', avg(surveys.map(s => s.ratings.materialsMerit)).toString()],
  ];

  slide2.addTable(mainMetrics, { x: 0.5, y: 1.2, w: 9, border: { type: 'solid', color: 'E2E8F0' }, fill: { color: 'FFFFFF' }, fontSize: 18 });

  // Slide 3: Trainers
  const slide3 = pres.addSlide();
  slide3.addText('Ocena Kadry Trenerskiej', { x: 0.5, y: 0.5, fontSize: 28, color: 'f97316', bold: true });

  const trainers = ['luiza', 'krzysztof', 'anna', 'tomasz'];
  const trainerRows = [['Trener', 'Merytoryka', 'Dydaktyka', 'Komunikacja', 'Śr. Ogólna']];

  trainers.forEach(t => {
    const knowledge = avg(surveys.map(s => (s.trainerRatings as any)[t].knowledge));
    if (knowledge > 0) {
      trainerRows.push([
        t.toUpperCase(),
        knowledge.toString(),
        avg(surveys.map(s => (s.trainerRatings as any)[t].didactics)).toString(),
        avg(surveys.map(s => (s.trainerRatings as any)[t].engagement)).toString(),
        avg([knowledge, avg(surveys.map(s => (s.trainerRatings as any)[t].didactics))]).toString()
      ]);
    }
  });

  slide3.addTable(trainerRows, { x: 0.5, y: 1.2, w: 9, fontSize: 14, border: { type: 'solid', color: 'E2E8F0' } });

  // Slide 4: Comments
  const slide4 = pres.addSlide();
  slide4.addText('Głos Uczestników - Mocne Strony', { x: 0.5, y: 0.5, fontSize: 24, color: '22c55e', bold: true });
  const pos = surveys.map(s => s.comments.positive).filter(c => c && c.length > 5).slice(0, 8);
  slide4.addText(pos.map(p => `• ${p}`).join('\n'), { x: 0.5, y: 1.2, w: 9, h: 4, fontSize: 12, color: '475569' });

  pres.writeFile({ fileName: `Raport_Quest_${new Date().toISOString().slice(0,10)}.pptx` });
};

