import { GoogleGenAI, Type } from "@google/genai";
import { SurveyRecord } from "../types";

const SYSTEM_INSTRUCTION = `
You are an expert OCR and data extraction assistant specialized in Polish training evaluation surveys from "QUEST".
Your task is to analyze documents (images or PDFs) of handwritten/circled surveys and extract data into a structured JSON format.

A document (especially a PDF) can contain:
1. A single survey spanning multiple pages.
2. Many different surveys scanned into one file (one after another).

Your goal is to find ALL surveys within the provided input and return them as an array.

CRITICAL RULES:
- Ratings (1-6): Look for circled numbers or marks.
- Trainers: There are sections for Luiza, Krzysztof, Anna, Tomasz. Extract all their scores.
- Text: Transcribe handwritten Polish comments exactly as they appear.
- Empty fields: Use null for numbers and empty string for text.
- ID generation: Do not provide IDs, the app will handle it.
`;

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    surveys: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          trainingTitle: { type: Type.STRING },
          date: { type: Type.STRING },
          place: { type: Type.STRING },
          ratings: {
            type: Type.OBJECT,
            properties: {
              organization: { type: Type.NUMBER },
              methods: { type: Type.NUMBER },
              practicality: { type: Type.NUMBER },
              materialsClarity: { type: Type.NUMBER },
              materialsMerit: { type: Type.NUMBER }
            }
          },
          trainerRatings: {
            type: Type.OBJECT,
            properties: {
              luiza: { 
                type: Type.OBJECT, 
                properties: { 
                  knowledge: { type: Type.NUMBER }, 
                  didactics: { type: Type.NUMBER }, 
                  preparation: { type: Type.NUMBER }, 
                  engagement: { type: Type.NUMBER }, 
                  culture: { type: Type.NUMBER } 
                } 
              },
              krzysztof: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              anna: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              tomasz: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } }
            }
          },
          comments: {
            type: Type.OBJECT,
            properties: {
              positive: { type: Type.STRING },
              negative: { type: Type.STRING },
              suggestions: { type: Type.STRING }
            }
          }
        }
      }
    }
  }
};

export async function processSurveyFiles(files: { data: string, mimeType: string }[]): Promise<SurveyRecord[]> {
  // Always use process.env.API_KEY directly as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const mediaParts = files.map(file => ({
    inlineData: {
      mimeType: file.mimeType,
      data: file.data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      // Use gemini-3-pro-preview for complex reasoning and data extraction tasks
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          ...mediaParts,
          { text: "Detect and extract all evaluation surveys from this document. If it's a multi-page PDF, look for surveys on all pages." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("AI returned an empty response.");

    const result = JSON.parse(text);
    return (result.surveys || []).map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}-${Math.random().toString(36).substr(2, 9)}`
    }));
  } catch (error: any) {
    console.error("Gemini API Error Detail:", error);
    if (error.message?.includes("413")) {
      throw new Error("Plik jest zbyt duży dla modelu AI. Spróbuj go podzielić.");
    }
    throw error;
  }
}

import React, { useState } from 'react';
import { processSurveyFiles } from '../services/geminiService';
import { SurveyRecord } from '../types';

interface SurveyUploaderProps {
  onDataLoaded: (data: SurveyRecord[], fileName: string) => void;
}

export const SurveyUploader: React.FC<SurveyUploaderProps> = ({ onDataLoaded }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const fileToData = (file: File): Promise<{ data: string, mimeType: string, name: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve({
          data: base64,
          mimeType: file.type || (file.name.endsWith('.pdf') ? 'application/pdf' : 'application/octet-stream'),
          name: file.name
        });
      };
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    setIsProcessing(true);
    setError(null);
    setProgress(5);

    try {
      // Fix: Explicitly cast Array.from(files) to File[] to ensure proper type inference for downstream operations
      const fileList = Array.from(files) as File[];
      const processedFiles = await Promise.all(fileList.map(fileToData));

      setProgress(20);

      const allExtractedSurveys: SurveyRecord[] = [];
      // Używamy nazwy pierwszego pliku jako identyfikatora zbioru, jeśli jest ich kilka
      const primaryFileName = fileList[0].name;

      for (let i = 0; i < processedFiles.length; i++) {
        const fileObj = processedFiles[i];
        try {
          const results = await processSurveyFiles([fileObj]);
          allExtractedSurveys.push(...results);
        } catch (singleFileErr: any) {
          console.error(`Błąd pliku ${fileObj.name}:`, singleFileErr);
        }

        const currentProgress = 20 + Math.floor(((i + 1) / processedFiles.length) * 80);
        setProgress(currentProgress);
      }

      if (allExtractedSurveys.length === 0) {
        throw new Error("Nie udało się wyodrębnić żadnych danych z przesłanych plików.");
      }

      onDataLoaded(allExtractedSurveys, primaryFileName);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "Wystąpił nieoczekiwany błąd podczas przetwarzania.");
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-8 border border-slate-200">
      <div className="max-w-xl mx-auto text-center">
        <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-file-pdf text-3xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Prześlij ankiety</h2>
        <p className="text-slate-500 mb-8">
          Wybierz skany lub zdjęcia. Obsługujemy pliki <b>PDF, JPG oraz PNG</b>.
        </p>

        {!isProcessing ? (
          <label className="relative group cursor-pointer">
            <div className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 group-hover:border-orange-400 rounded-xl p-10 transition-colors">
              <i className="fa-solid fa-cloud-arrow-up text-4xl text-slate-400 group-hover:text-orange-500 mb-4"></i>
              <span className="text-slate-600 font-medium">Kliknij, aby wybrać pliki</span>
              <span className="text-slate-400 text-sm mt-1">Akceptowane: .pdf, .jpg, .jpeg, .png</span>
            </div>
            <input 
              type="file" 
              multiple 
              className="hidden" 
              accept=".pdf,image/*" 
              onChange={handleFileUpload}
            />
          </label>
        ) : (
          <div className="space-y-4">
            <div className="h-4 bg-slate-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-orange-500 transition-all duration-500" 
                style={{ width: `${progress}%` }}
              ></div>
            </div>
            <p className="text-slate-600 font-medium animate-pulse">
              Analizowanie dokumentów... ({progress}%)
            </p>
          </div>
        )}

        {error && (
          <div className="mt-6 p-4 bg-red-50 text-red-700 rounded-lg border border-red-100 flex items-start gap-3 text-left">
            <i className="fa-solid fa-circle-exclamation mt-0.5 flex-shrink-0"></i>
            <div>
              <p className="font-bold text-sm">Błąd przetwarzania</p>
              <p className="text-xs mt-1">{error}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

