              materialsMerit: { type: Type.NUMBER }
            }
          },
          trainerRatings: {
            type: Type.OBJECT,
            properties: {
              luiza: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              krzysztof: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              anna: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } },
              tomasz: { type: Type.OBJECT, properties: { knowledge: { type: Type.NUMBER }, didactics: { type: Type.NUMBER }, preparation: { type: Type.NUMBER }, engagement: { type: Type.NUMBER }, culture: { type: Type.NUMBER } } }
            }
          },
          comments: {
            type: Type.OBJECT,
            properties: {
              positive: { type: Type.STRING },
              negative: { type: Type.STRING },
              suggestions: { type: Type.STRING }
            }
          }
        }
      }
    }
  }
};

export async function processSurveyFiles(files: { data: string, mimeType: string }[]): Promise<SurveyRecord[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const mediaParts = files.map(file => ({
    inlineData: {
      mimeType: file.mimeType,
      data: file.data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          ...mediaParts,
          { text: "Wyodrębnij wszystkie ankiety. Zwróć TYLKO czysty JSON." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        // Dodajemy budżet na myślenie, aby model lepiej radził sobie z nieczytelnym pismem
        thinkingConfig: { thinkingBudget: 4000 } 
      }
    });

    let text = response.text || "";
    // Oczyszczanie na wypadek, gdyby model nie zwrócił czystego JSON mimo konfiguracji
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    if (!text) throw new Error("Model AI nie zwrócił żadnych danych.");

    const result = JSON.parse(text);
    return (result.surveys || []).map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}-${Math.random().toString(36).substr(2, 5)}`
    }));
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { processSurveyFiles } from '../services/geminiService';
import { SurveyRecord } from '../types';

interface SurveyUploaderProps {
  onDataLoaded: (data: SurveyRecord[], fileName: string) => void;
}

export const SurveyUploader: React.FC<SurveyUploaderProps> = ({ onDataLoaded }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusLabel, setStatusLabel] = useState("");
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Efekt symulujący pracę, gdy AI myśli (płynny pasek)
  useEffect(() => {
    let interval: any;
    if (isProcessing && progress >= 20 && progress < 90) {
      interval = setInterval(() => {
        setProgress(prev => Math.min(prev + 0.5, 90));
      }, 500);
    }
    return () => clearInterval(interval);
  }, [isProcessing, progress]);

  const fileToData = (file: File): Promise<{ data: string, mimeType: string, name: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve({
          data: base64,
          mimeType: file.type || (file.name.endsWith('.pdf') ? 'application/pdf' : 'application/octet-stream'),
          name: file.name
        });
      };
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileName = files[0].name;
    setIsProcessing(true);
    setError(null);
    setProgress(5);
    setStatusLabel("Wczytywanie pliku do pamięci...");

    try {
      const fileList = Array.from(files) as File[];
      const processedFiles = await Promise.all(fileList.map(fileToData));

      setProgress(20);
      setStatusLabel("AI analizuje pismo ręczne i skany (to może potrwać chwilę)...");

      const allExtractedSurveys: SurveyRecord[] = [];

      for (let i = 0; i < processedFiles.length; i++) {
        if (i > 0) setStatusLabel(`Przetwarzanie dokumentu ${i+1} z ${processedFiles.length}...`);

        try {
          const results = await processSurveyFiles([processedFiles[i]]);
          allExtractedSurveys.push(...results);
        } catch (singleFileErr: any) {
          console.error(`Błąd pliku:`, singleFileErr);
        }
      }

      if (allExtractedSurveys.length === 0) {
        throw new Error("Nie udało się odczytać żadnych danych. Upewnij się, że skany są czytelne.");
      }

      setStatusLabel("Finalizowanie i zapisywanie danych...");
      setProgress(100);

      // Krótkie opóźnienie dla UX
      setTimeout(() => {
        onDataLoaded(allExtractedSurveys, fileName);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }, 800);

    } catch (err: any) {
      setError(err.message || "Wystąpił błąd. Spróbuj mniejszego pliku.");
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-8 border border-slate-200">
      <div className="max-w-xl mx-auto text-center">
        <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-file-pdf text-3xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Prześlij ankiety</h2>
        <p className="text-slate-500 mb-8">
          Obsługujemy pliki <b>PDF, JPG oraz PNG</b>. Gemini 3 Pro przeanalizuje pismo ręczne.
        </p>

        {!isProcessing ? (
          <label className="relative group cursor-pointer block">
            <div className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 group-hover:border-orange-400 rounded-xl p-10 transition-all hover:bg-orange-50/30">
              <i className="fa-solid fa-cloud-arrow-up text-4xl text-slate-400 group-hover:text-orange-500 mb-4 transition-transform group-hover:-translate-y-1"></i>
              <span className="text-slate-600 font-bold">Wybierz dokumenty do analizy</span>
              <span className="text-slate-400 text-xs mt-1 uppercase tracking-widest font-bold">Max 20MB na plik</span>
            </div>
            <input 
              ref={fileInputRef}
              type="file" 
              multiple 
              className="hidden" 
              accept=".pdf,image/*" 
              onChange={handleFileUpload}
            />
          </label>
        ) : (
          <div className="space-y-6 py-4">
            <div className="relative pt-1">
              <div className="flex mb-2 items-center justify-between">
                <div>
                  <span className="text-xs font-bold inline-block py-1 px-2 uppercase rounded-full text-orange-600 bg-orange-100">
                    {progress < 100 ? 'W toku' : 'Gotowe'}
                  </span>
                </div>
                <div className="text-right">
                  <span className="text-xs font-bold inline-block text-orange-600">
                    {Math.round(progress)}%
                  </span>
                </div>
              </div>
              <div className="overflow-hidden h-2 mb-4 text-xs flex rounded bg-orange-50">
                <div 
                  style={{ width: `${progress}%` }} 
                  className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-orange-500 transition-all duration-300"
                ></div>
              </div>
            </div>
            <div className="flex items-center justify-center gap-3 text-slate-600">
              <i className="fa-solid fa-circle-notch fa-spin text-orange-500"></i>
              <p className="font-bold text-sm tracking-tight">{statusLabel}</p>
            </div>
            <p className="text-[10px] text-slate-400 uppercase font-bold">Nie odświeżaj strony podczas pracy AI</p>
          </div>
        )}

        {error && (
          <div className="mt-6 p-4 bg-red-50 text-red-700 rounded-lg border border-red-100 flex items-start gap-3 text-left animate-in slide-in-from-top-2">
            <i className="fa-solid fa-circle-exclamation mt-0.5 flex-shrink-0"></i>
            <div>
              <p className="font-bold text-sm">Przerwano pracę</p>
              <p className="text-xs mt-1">{error}</p>
              <button onClick={() => setError(null)} className="mt-2 text-xs font-bold underline">Spróbuj ponownie</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

