export async function processSurveyFiles(files: { data: string, mimeType: string }[]): Promise<SurveyRecord[]> {
  // Używamy nowej instancji dla każdego żądania, aby mieć pewność co do klucza i stanu
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const mediaParts = files.map(file => ({
    inlineData: {
      mimeType: file.mimeType,
      data: file.data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          ...mediaParts,
          { text: "Wyodrębnij wszystkie ankiety z tego dokumentu. Zwróć dane w formacie JSON." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        // Zwiększamy budżet na myślenie do 8000 dla trudnych skanów
        thinkingConfig: { thinkingBudget: 8000 }
      }
    });

    const rawText = response.text || "";
    // Bardziej agresywne czyszczenie tekstu, aby uniknąć błędów JSON.parse
    const jsonMatch = rawText.match(/\{[\s\S]*\}/);
    const textToParse = jsonMatch ? jsonMatch[0] : rawText;

    if (!textToParse) throw new Error("Błąd struktury danych zwróconych przez AI.");

    const result = JSON.parse(textToParse);
    return (result.surveys || []).map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}-${Math.random().toString(36).substr(2, 5)}`
    }));
  } catch (error: any) {
    console.error("Szczegóły błędu Gemini:", error);
    throw error;
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { processSurveyFiles } from '../services/geminiService';
