  useEffect(() => {
    let interval: any;
    if (isProcessing) {
      interval = setInterval(() => {
        setWorkingSeconds(prev => prev + 1);
      }, 1000);
    } else {
      setWorkingSeconds(0);
    }
    return () => clearInterval(interval);
  }, [isProcessing]);

  const fileToData = (file: File): Promise<{ data: string, mimeType: string, name: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve({
          data: base64,
          mimeType: file.type || (file.name.endsWith('.pdf') ? 'application/pdf' : 'application/octet-stream'),
          name: file.name
        });
      };
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileName = files[0].name;
    setIsProcessing(true);
    setError(null);
    setProgress(5);
    setStatusLabel("Wczytywanie dokumentów...");

    try {
      const fileList = Array.from(files) as File[];
      const processedFiles = await Promise.all(fileList.map(fileToData));

      const allExtractedSurveys: SurveyRecord[] = [];
      const totalFiles = processedFiles.length;

      for (let i = 0; i < totalFiles; i++) {
        // Obliczamy postęp bazując na aktualnym pliku
        const baseProgress = 10 + (i / totalFiles) * 85;
        setProgress(baseProgress);
        setStatusLabel(`Analiza dokumentu ${i + 1} z ${totalFiles}...`);

        try {
          const results = await processSurveyFiles([processedFiles[i]]);
          allExtractedSurveys.push(...results);
        } catch (singleFileErr: any) {
          console.error(`Błąd przy pliku ${processedFiles[i].name}:`, singleFileErr);
          // Jeśli to jedyny plik, wyrzuć błąd. Jeśli jest ich więcej, kontynuuj.
          if (totalFiles === 1) throw singleFileErr;
        }
      }

      if (allExtractedSurveys.length === 0) {
        throw new Error("AI nie wykryło żadnych ankiet. Sprawdź czy plik nie jest pusty lub zbyt słabej jakości.");
      }

      setStatusLabel("Finalizowanie danych...");
      setProgress(100);

      setTimeout(() => {
        onDataLoaded(allExtractedSurveys, fileName);
        if (fileInputRef.current) fileInputRef.current.value = '';
        setIsProcessing(false);
      }, 1000);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Błąd połączenia z AI. Spróbuj mniejszego dokumentu.");
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-8 border border-slate-200">
      <div className="max-w-xl mx-auto text-center">
        <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mx-auto mb-6">
