import { GoogleGenAI, Type } from "@google/genai";
import { SurveyRecord } from "../types";

const SYSTEM_INSTRUCTION = `
Jesteś zaawansowanym systemem OCR wyspecjalizowanym w analizie ankiet papierowych firmy "QUEST". 
Twoim zadaniem jest przekształcenie obrazów lub dokumentów PDF na ustrukturyzowane dane JSON.

ZASADY ANALIZY:
1. IDENTYFIKACJA ANKIET: Na jednej stronie może znajdować się jedna lub więcej ankiet. Wyodrębnij KAŻDĄ z nich jako osobny obiekt w tablicy "surveys".
2. OCENY: Szukaj zakreślonych kółek, krzyżyków lub podkreśleń przy cyfrach 1-6. Jeśli ocena jest niejednoznaczna, wybierz najbardziej prawdopodobną lub wpisz null.
3. TRENERZY: W ankiecie są sekcje dla trenerów (Luiza, Krzysztof, Anna, Tomasz). Przypisz oceny do właściwych osób.
4. PISMO RĘCZNE: Przepisz komentarze (Plusy, Minusy, Sugestie) słowo w słowo. Jeśli pismo jest nieczytelne, wpisz "[nieczytelne]".
5. DATY I MIEJSCA: Zidentyfikuj datę szkolenia (format DD.MM.YYYY) oraz tytuł szkolenia i miejsce.

STRUKTURA WYJŚCIOWA (JSON):
Zwróć WYŁĄCZNIE obiekt JSON o następującej strukturze:
{
  "surveys": [
    {
      "trainingTitle": "string",
      "date": "string",
      "place": "string",
      "ratings": { "organization": number|null, "methods": number|null, "practicality": number|null, "materialsClarity": number|null, "materialsMerit": number|null },
      "trainerRatings": {
        "luiza": { "knowledge": n|null, "didactics": n|null, "preparation": n|null, "engagement": n|null, "culture": n|null },
        "krzysztof": { ... },
        "anna": { ... },
        "tomasz": { ... }
      },
      "comments": { "positive": "string", "negative": "string", "suggestions": "string" }
    }
  ]
}

WAŻNE: Nie dodawaj żadnego tekstu przed ani po JSON. Jeśli nie znajdziesz żadnych ankiet, zwróć {"surveys": []}.
`;

export async function processSurveyFiles(files: { data: string, mimeType: string }[]): Promise<SurveyRecord[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const mediaParts = files.map(file => ({
    inlineData: {
      mimeType: file.mimeType,
      data: file.data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          ...mediaParts,
          { text: "Przeanalizuj te dokumenty i wyodrębnij wszystkie dane ankietowe do formatu JSON. Skup się na dokładnym odczycie pisma ręcznego i ocen 1-6." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        // Bardzo wysoki budżet na myślenie dla głębokiej analizy OCR
        thinkingConfig: { thinkingBudget: 16000 }
      }
    });

    const rawText = response.text || "";

    // Zaawansowane czyszczenie tekstu (obsługa markdown i śmieci tekstowych)
    let jsonStr = rawText.trim();
    if (jsonStr.includes('```')) {
      const match = jsonStr.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
      if (match) jsonStr = match[1];
    }

    // Dodatkowe zabezpieczenie: znajdź pierwszy '{' i ostatni '}'
    const firstBrace = jsonStr.indexOf('{');
    const lastBrace = jsonStr.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
      jsonStr = jsonStr.substring(firstBrace, lastBrace + 1);
    }

    if (!jsonStr) throw new Error("Model AI nie wygenerował poprawnego formatu danych.");

    const result = JSON.parse(jsonStr);

    if (!result.surveys || !Array.isArray(result.surveys)) {
      if (Object.keys(result).length > 0 && !result.surveys) {
         // Próba ratowania sytuacji, gdyby model pominął klucz "surveys"
         return [{ ...result, id: crypto.randomUUID() }] as any;
      }
      return [];
    }

    return result.surveys.map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}-${Math.random().toString(36).substring(2, 7)}`
    }));
  } catch (error: any) {
    console.error("Krytyczny błąd Gemini Service:", error);
    // Przekazujemy czytelniejszy komunikat błędu
    if (error.message?.includes("Unexpected token")) {
      throw new Error("Błąd interpretacji danych AI. Spróbuj przesłać mniej stron na raz.");
    }
    throw error;
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { processSurveyFiles } from '../services/geminiService';
import { SurveyRecord } from '../types';

interface SurveyUploaderProps {
  onDataLoaded: (data: SurveyRecord[], fileName: string) => void;
}

export const SurveyUploader: React.FC<SurveyUploaderProps> = ({ onDataLoaded }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusLabel, setStatusLabel] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [workingSeconds, setWorkingSeconds] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    let interval: any;
    if (isProcessing) {
      interval = setInterval(() => {
        setWorkingSeconds(prev => prev + 1);

        // Dynamiczne zmiany statusu w zależności od czasu
        if (workingSeconds > 15 && workingSeconds <= 30) setStatusLabel("AI intensywnie analizuje pismo ręczne...");
        if (workingSeconds > 30 && workingSeconds <= 60) setStatusLabel("Duży dokument. Rozpoznawanie tabel i ocen...");
        if (workingSeconds > 60) setStatusLabel("Prawie gotowe, model kończy generować raport JSON...");
      }, 1000);
    } else {
      setWorkingSeconds(0);
    }
    return () => clearInterval(interval);
  }, [isProcessing, workingSeconds]);

  const fileToData = (file: File): Promise<{ data: string, mimeType: string, name: string }> => {
    return new Promise((resolve, reject) => {
      if (file.size > 20 * 1024 * 1024) {
        reject(new Error(`Plik ${file.name} jest za duży (max 20MB).`));
        return;
      }
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve({
          data: base64,
          mimeType: file.type || (file.name.endsWith('.pdf') ? 'application/pdf' : 'application/octet-stream'),
          name: file.name
        });
      };
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileName = files[0].name;
    setIsProcessing(true);
    setError(null);
    setProgress(5);
    setStatusLabel("Przygotowanie plików...");

    try {
      const fileList = Array.from(files) as File[];
      const processedFiles = await Promise.all(fileList.map(fileToData));

      const allExtractedSurveys: SurveyRecord[] = [];
      const totalFiles = processedFiles.length;

      for (let i = 0; i < totalFiles; i++) {
        const currentFile = processedFiles[i];
        setStatusLabel(`Wysyłanie pliku ${i + 1} z ${totalFiles} do AI...`);
        setProgress(10 + (i / totalFiles) * 80);

        try {
          // Wysyłamy pliki pojedynczo, aby uniknąć limitów wielkości zapytania
          const results = await processSurveyFiles([currentFile]);
          if (results && results.length > 0) {
            allExtractedSurveys.push(...results);
          }
        } catch (singleFileErr: any) {
          console.error(`Błąd pliku ${currentFile.name}:`, singleFileErr);
          if (totalFiles === 1) throw singleFileErr;
          // Jeśli wiele plików, kontynuujemy mimo błędu jednego z nich
        }
      }

      if (allExtractedSurveys.length === 0) {
        throw new Error("AI nie odnalazło żadnych czytelnych danych ankietowych w przesłanych plikach. Upewnij się, że skany są wyraźne.");
      }

      setStatusLabel("Zakończono sukcesem!");
      setProgress(100);

      setTimeout(() => {
        onDataLoaded(allExtractedSurveys, fileName);
        if (fileInputRef.current) fileInputRef.current.value = '';
        setIsProcessing(false);
      }, 800);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Wystąpił nieoczekiwany błąd. Spróbuj odświeżyć stronę lub przesłać mniejszy dokument.");
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl p-10 border border-slate-200">
      <div className="max-w-xl mx-auto text-center">
        <div className="w-24 h-24 bg-orange-100 text-orange-600 rounded-3xl flex items-center justify-center mx-auto mb-8 rotate-3 shadow-inner">
          <i className="fa-solid fa-wand-magic-sparkles text-4xl"></i>
        </div>
        <h2 className="text-3xl font-extrabold text-slate-800 mb-3 tracking-tight">Analiza AI 2.0</h2>
        <p className="text-slate-500 mb-10 leading-relaxed">
          Nasz model <b>Gemini 3 Pro</b> został zoptymalizowany pod kątem trudnego pisma ręcznego i wielostronicowych dokumentów PDF.
        </p>

        {!isProcessing ? (
          <label className="relative group cursor-pointer block">
            <div className="flex flex-col items-center justify-center border-4 border-dashed border-slate-200 group-hover:border-orange-400 group-hover:bg-orange-50/30 rounded-3xl p-12 transition-all duration-300">
              <i className="fa-solid fa-cloud-arrow-up text-5xl text-slate-300 group-hover:text-orange-500 mb-6 transition-transform group-hover:-translate-y-2"></i>
              <span className="text-slate-700 font-bold text-lg">Wgraj ankiety (PDF/JPG)</span>
              <span className="text-slate-400 text-sm mt-2 font-medium">Kliknij lub przeciągnij pliki tutaj</span>
            </div>
            <input 
              ref={fileInputRef}
              type="file" 
              multiple 
              className="hidden" 
              accept=".pdf,image/*" 
              onChange={handleFileUpload}
            />
          </label>
        ) : (
          <div className="space-y-8 py-6">
            <div className="relative pt-1">
              <div className="flex mb-4 items-center justify-between">
                <span className="text-xs font-black uppercase tracking-tighter px-3 py-1 bg-orange-500 text-white rounded-full animate-pulse">
                  Analiza w toku
                </span>
                <span className="text-sm font-black text-orange-600">
                  {Math.round(progress)}%
                </span>
              </div>
              <div className="overflow-hidden h-4 mb-4 text-xs flex rounded-full bg-slate-100 shadow-inner">
                <div 
                  style={{ width: `${progress}%` }} 
                  className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-gradient-to-r from-orange-400 to-orange-600 transition-all duration-1000 ease-in-out"
                ></div>
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200 shadow-sm">
               <div className="flex items-center justify-center gap-4 text-slate-700">
                <i className="fa-solid fa-sync fa-spin text-orange-500 text-xl"></i>
                <p className="font-bold text-base tracking-tight">{statusLabel}</p>
              </div>
              <div className="mt-4 flex justify-center items-center gap-2">
                <span className="w-2 h-2 bg-orange-400 rounded-full animate-bounce"></span>
                <span className="w-2 h-2 bg-orange-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                <span className="w-2 h-2 bg-orange-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
              </div>
              <p className="text-[11px] text-slate-400 mt-4 uppercase font-bold tracking-widest">
                Czas operacji: {workingSeconds} sekund
              </p>
            </div>

            <div className="flex items-center justify-center gap-2 text-amber-600 bg-amber-50 p-3 rounded-xl border border-amber-100">
              <i className="fa-solid fa-triangle-exclamation"></i>
              <p className="text-[11px] font-bold uppercase">Nie zamykaj okna przeglądarki</p>
            </div>
          </div>
        )}

        {error && (
          <div className="mt-8 p-6 bg-red-50 text-red-700 rounded-2xl border border-red-200 text-left animate-in slide-in-from-top-4 shadow-sm">
            <div className="flex gap-4">
              <i className="fa-solid fa-circle-xmark text-2xl mt-1"></i>
              <div>
                <p className="font-black text-lg leading-tight">Analiza przerwana</p>
                <p className="text-sm mt-2 leading-relaxed opacity-90">{error}</p>
                <div className="flex gap-3 mt-5">
                  <button 
                    onClick={() => { setError(null); if (fileInputRef.current) fileInputRef.current.click(); }} 
                    className="px-5 py-2 bg-white text-red-600 font-bold text-xs rounded-xl border border-red-200 hover:bg-red-100 transition-all shadow-sm"
                  >
                    Wybierz inny plik
                  </button>
                  <button 
                    onClick={() => setError(null)} 
                    className="px-5 py-2 text-red-400 font-bold text-xs hover:text-red-600 transition-colors"
