                <div className="flex items-center gap-2">
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Historyczny Tracking</p>
                  {isAdmin && <span className="bg-orange-100 text-orange-600 text-[8px] font-black px-1.5 py-0.5 rounded uppercase">Admin</span>}
                </div>
