              <button 
                disabled={surveys.length === 0}
                onClick={() => setActiveTab(AppTab.EDA)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === AppTab.EDA ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50 disabled:opacity-30'}`}
