                  <>
                    <button onClick={() => exportToExcel(filteredSurveys)} className="p-2 text-green-600 hover:bg-green-50 rounded-lg border border-green-100" title="Excel"><i className="fa-solid fa-file-excel"></i></button>
                    <button onClick={() => exportToPDF(filteredSurveys)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg border border-red-100" title="PDF"><i className="fa-solid fa-file-pdf"></i></button>
                    {isAdmin && (
                      <button onClick={clearAllData} className="text-slate-300 hover:text-red-500 transition-colors p-2" title="Wyczyść całą bazę"><i className="fa-solid fa-trash-can"></i></button>
                    )}
                  </>
                )}
                <div className="w-px h-6 bg-slate-200 mx-2"></div>
                {!isAdmin ? (
                  <button 
                    onClick={() => setShowLoginModal(true)}
                    className="px-4 py-1.5 bg-slate-800 text-white text-xs font-bold rounded-full hover:bg-slate-700 transition-colors flex items-center gap-2"
                  >
                    <i className="fa-solid fa-lock text-[10px]"></i> ZALOGUJ
