                  <button 
                    onClick={handleLogout}
                    className="px-4 py-1.5 bg-red-50 text-red-600 text-xs font-bold rounded-full hover:bg-red-100 transition-colors flex items-center gap-2"
                  >
                    <i className="fa-solid fa-power-off text-[10px]"></i> WYLOGUJ
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Login Modal */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-8 border border-slate-200 scale-in-center">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                <i className="fa-solid fa-shield-halved text-2xl"></i>
              </div>
              <h2 className="text-2xl font-black text-slate-800">Panel Admina</h2>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Zaloguj się aby zarządzać</p>
            </div>

            <form onSubmit={handleLogin} className="space-y-4">
