              <label className="text-[9px] uppercase font-black text-slate-500">Kwartał:</label>
              <div className="flex gap-1">
                {['all', 'I', 'II', 'III', 'IV'].map(q => (
                  <button 
                    key={q} 
                    onClick={() => setSelectedQuarter(q)}
