            <div className="flex items-center gap-2 flex-1">
              <label className="text-[9px] uppercase font-black text-slate-500">Zbiór:</label>
              <div className="flex gap-2 flex-1 max-w-md">
                <select 
                  value={selectedFile} 
                  onChange={(e) => setSelectedFile(e.target.value)}
                  className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-xs flex-1 focus:ring-1 focus:ring-orange-500 outline-none font-bold text-orange-400"
                >
                  <option value="all">Wszystkie wgrane pliki</option>
                  {uniqueFiles.map(f => <option key={f} value={f}>{f}</option>)}
                </select>
                {isAdmin && selectedFile !== 'all' && (
                  <button 
                    onClick={deleteSelectedFileSet}
                    className="px-3 py-1 bg-red-900/40 hover:bg-red-600 text-red-100 rounded text-[9px] font-black transition-all border border-red-700 flex items-center gap-1"
                  >
                    <i className="fa-solid fa-trash-can"></i> USUŃ
                  </button>
                )}
              </div>
            </div>

            <div className="text-[9px] bg-black/40 px-3 py-1.5 rounded-full text-slate-400 border border-slate-800 font-black">
              WYNIKI: <span className="text-orange-400">{filteredSurveys.length}</span> / {surveys.length} ANKIET
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === AppTab.UPLOAD && isAdmin && (
          <div className="animate-in fade-in duration-500 slide-in-from-bottom-4">
            <SurveyUploader onDataLoaded={handleDataLoaded} />
          </div>
        )}

        {filteredSurveys.length > 0 ? (
          <>
            {activeTab === AppTab.SUMMARY && <SummaryDashboard surveys={filteredSurveys} />}
            {activeTab === AppTab.TABLE && <DetailedTableView surveys={filteredSurveys} />}
            {activeTab === AppTab.EDA && <EDADashboard surveys={filteredSurveys} />}
          </>
        ) : surveys.length > 0 && activeTab !== AppTab.UPLOAD ? (
          <div className="bg-white p-20 rounded-2xl border-2 border-dashed border-slate-200 text-center">
            <i className="fa-solid fa-filter-circle-xmark text-5xl text-slate-200 mb-4"></i>
            <h3 className="text-xl font-bold text-slate-800">Brak wyników</h3>
            <p className="text-slate-500 mt-2 text-sm font-medium">Spróbuj zmienić filtry czasowe lub wybierz inny zbiór danych.</p>
          </div>
        ) : !isAdmin && surveys.length === 0 ? (
          <div className="bg-white p-20 rounded-3xl border border-slate-200 text-center shadow-sm">
             <i className="fa-solid fa-database text-6xl text-slate-100 mb-6"></i>
             <h2 className="text-2xl font-black text-slate-800">Baza danych jest obecnie pusta</h2>
             <p className="text-slate-500 mt-4 max-w-md mx-auto font-medium">System czeka na wgranie pierwszych ankiet przez Administratora systemu.</p>
          </div>
        ) : null}
      </main>

      <footer className="bg-white border-t border-slate-200 py-8 text-center text-slate-400 text-[9px] uppercase tracking-widest font-black">
        <p>© {new Date().getFullYear()} Quest Survey Insights • Security Protocol: {isAdmin ? 'ADMIN_ACCESS' : 'GUEST_VIEW'}</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
