            {surveys.filter(s => s.comments.negative).map((s, i) => (
              <div key={i} className="p-4 bg-red-50/50 rounded-xl border border-red-100 text-slate-700 text-xs italic leading-relaxed shadow-sm">
                "{s.comments.negative}"
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm p-6 border border-slate-200">
          <h3 className="text-[10px] font-black text-orange-600 mb-5 uppercase tracking-widest flex items-center gap-2">
