import React, { useState, useEffect, useMemo } from 'react';
import { AppTab, SurveyRecord } from './types';
import { SurveyUploader } from './components/SurveyUploader';
import { SummaryDashboard } from './components/SummaryDashboard';
import { DetailedTableView } from './components/DetailedTableView';
import { EDADashboard } from './components/EDADashboard';
import { exportToExcel, exportToPDF } from './utils/exportUtils';

const STORAGE_KEY = 'quest_survey_data_v2';
const AUTH_KEY = 'quest_admin_auth_v2';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.SUMMARY);
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [isAdmin, setIsAdmin] = useState<boolean>(false);
  const [showLoginModal, setShowLoginModal] = useState<boolean>(false);
  const [loginData, setLoginData] = useState({ login: '', password: '' });
  const [loginError, setLoginError] = useState('');
  const [isInitialized, setIsInitialized] = useState(false);

  // Filtry
  const [selectedYear, setSelectedYear] = useState<string>('all');
  const [selectedQuarter, setSelectedQuarter] = useState<string>('all');
  const [selectedFile, setSelectedFile] = useState<string>('all');

  useEffect(() => {
    // Inicjalizacja danych z localStorage
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSurveys(parsed);
      } catch (e) {
        console.error("Błąd ładowania danych", e);
      }
    }

    // Sprawdzenie sesji admina
    const auth = sessionStorage.getItem(AUTH_KEY);
    if (auth === 'true') setIsAdmin(true);

    setIsInitialized(true);
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(surveys));
    }
  }, [surveys, isInitialized]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginData.login === 'ADMIN' && loginData.password === 'Questan08!') {
      setIsAdmin(true);
      sessionStorage.setItem(AUTH_KEY, 'true');
      setShowLoginModal(false);
      setLoginError('');
      setLoginData({ login: '', password: '' });
    } else {
      setLoginError('Nieprawidłowy login lub hasło');
    }
  };

  const handleLogout = () => {
    setIsAdmin(false);
    sessionStorage.removeItem(AUTH_KEY);
    if (activeTab === AppTab.UPLOAD) setActiveTab(AppTab.SUMMARY);
  };

  const handleDataLoaded = (newSurveys: SurveyRecord[], fileName: string) => {
    if (!isAdmin) return;
    setSurveys(prev => [...prev, ...newSurveys.map(s => ({ ...s, fileName }))]);
    setSelectedFile(fileName);
    setActiveTab(AppTab.SUMMARY);
  };

  const deleteSelectedFileSet = () => {
    if (!isAdmin || selectedFile === 'all') return;
    if (confirm(`Czy na pewno usunąć zbiór: ${selectedFile}?`)) {
      setSurveys(prev => prev.filter(s => s.fileName !== selectedFile));
      setSelectedFile('all');
    }
  };

  const getQuarter = (dateStr: string) => {
    if (!dateStr) return null;
    const parts = dateStr.split('.');
    if (parts.length < 2) return null;
    const month = parseInt(parts[1], 10);
    if (month >= 1 && month <= 3) return 'I';
    if (month >= 4 && month <= 6) return 'II';
    if (month >= 7 && month <= 9) return 'III';
    if (month >= 10 && month <= 12) return 'IV';
    return null;
  };

  const getYear = (dateStr: string) => {
    if (!dateStr) return null;
    const parts = dateStr.split('.');
    return parts[parts.length - 1];
  };

  const filteredSurveys = useMemo(() => {
    return surveys.filter(s => {
      const year = getYear(s.date);
      const quarter = getQuarter(s.date);
      const matchYear = selectedYear === 'all' || year === selectedYear;
      const matchQuarter = selectedQuarter === 'all' || quarter === selectedQuarter;
      const matchFile = selectedFile === 'all' || s.fileName === selectedFile;
      return matchYear && matchQuarter && matchFile;
    });
  }, [surveys, selectedYear, selectedQuarter, selectedFile]);

  const uniqueFiles = useMemo(() => {
    return Array.from(new Set(surveys.map(s => s.fileName))).filter(Boolean) as string[];
  }, [surveys]);

  const clearAllData = () => {
    if (!isAdmin) return;
    if (confirm("UWAGA: Ta operacja nieodwracalnie usunie wszystkie ankiety z bazy. Kontynuować?")) {
      setSurveys([]);
    }
  };

  if (!isInitialized) return null;

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-orange-600 text-white p-2 rounded-xl shadow-md">
                <i className="fa-solid fa-chart-line text-xl"></i>
              </div>
              <div>
                <h1 className="text-xl font-black text-slate-800 tracking-tight">QUEST <span className="text-orange-600">ANALYTICS</span></h1>
                <div className="flex items-center gap-2">
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">System Analizy Ankiet</p>
                  {isAdmin && <span className="bg-orange-100 text-orange-600 text-[8px] font-black px-1.5 py-0.5 rounded uppercase border border-orange-200">Admin Mode</span>}
                </div>
              </div>
            </div>

            <nav className="hidden md:flex gap-1">
              {isAdmin && (
                <button 
                  onClick={() => setActiveTab(AppTab.UPLOAD)}
                  className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === AppTab.UPLOAD ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                  <i className="fa-solid fa-plus-circle mr-2"></i> Nowe Dane
                </button>
              )}
              <button 
                onClick={() => setActiveTab(AppTab.SUMMARY)}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === AppTab.SUMMARY ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                <i className="fa-solid fa-gauge-high mr-2"></i> Dashboard
              </button>
              <button 
                onClick={() => setActiveTab(AppTab.TABLE)}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === AppTab.TABLE ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                <i className="fa-solid fa-list-check mr-2"></i> Dane
              </button>
              <button 
                onClick={() => setActiveTab(AppTab.EDA)}
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === AppTab.EDA ? 'bg-orange-50 text-orange-600' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                <i className="fa-solid fa-chart-pie mr-2"></i> Statystyki
              </button>
            </nav>

            <div className="flex items-center gap-3">
              {surveys.length > 0 && (
                <div className="flex items-center gap-1 mr-4">
                  <button onClick={() => exportToExcel(filteredSurveys)} className="p-2 text-green-600 hover:bg-green-50 rounded-lg" title="Eksport Excel"><i className="fa-solid fa-file-excel"></i></button>
                  <button onClick={() => exportToPDF(filteredSurveys)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg" title="Eksport PDF"><i className="fa-solid fa-file-pdf"></i></button>
                </div>
              )}

              {!isAdmin ? (
                <button 
                  onClick={() => setShowLoginModal(true)}
                  className="px-4 py-2 bg-slate-800 text-white text-[11px] font-black rounded-xl hover:bg-slate-700 transition-all flex items-center gap-2"
                >
                  <i className="fa-solid fa-lock"></i> ZALOGUJ
                </button>
              ) : (
                <div className="flex items-center gap-2">
                  <button onClick={clearAllData} className="p-2 text-slate-300 hover:text-red-600 transition-colors" title="Wyczyść bazę"><i className="fa-solid fa-trash-can"></i></button>
                  <button 
                    onClick={handleLogout}
                    className="px-4 py-2 bg-red-600 text-white text-[11px] font-black rounded-xl hover:bg-red-700 transition-all flex items-center gap-2"
                  >
                    <i className="fa-solid fa-power-off"></i> WYLOGUJ
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* MODAL LOGOWANIA */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm p-10 border border-slate-200">
            <div className="text-center mb-8">
              <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-3xl flex items-center justify-center mx-auto mb-4 rotate-3">
                <i className="fa-solid fa-user-shield text-3xl"></i>
              </div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tight">Panel Administracyjny</h2>
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-2">Dostęp chroniony hasłem</p>
            </div>

            <form onSubmit={handleLogin} className="space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block ml-1">Login</label>
                <input 
                  autoFocus
                  type="text" 
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-4 focus:ring-orange-500/10 outline-none transition-all"
                  value={loginData.login}
                  onChange={e => setLoginData({...loginData, login: e.target.value})}
                  placeholder="ADMIN"
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block ml-1">Hasło</label>
                <input 
                  type="password" 
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-4 focus:ring-orange-500/10 outline-none transition-all"
                  value={loginData.password}
                  onChange={e => setLoginData({...loginData, password: e.target.value})}
                  placeholder="••••••••"
                />
              </div>
              {loginError && <p className="text-red-600 text-[10px] font-bold text-center bg-red-50 py-3 rounded-2xl">{loginError}</p>}
              <div className="flex gap-4 pt-4">
                <button 
                  type="button"
                  onClick={() => setShowLoginModal(false)}
                  className="flex-1 py-4 bg-slate-100 text-slate-500 font-bold text-xs rounded-2xl hover:bg-slate-200 transition-all"
                >
                  ANULUJ
                </button>
                <button 
                  type="submit"
                  className="flex-2 px-8 py-4 bg-orange-600 text-white font-black text-xs rounded-2xl hover:bg-orange-700 transition-all shadow-lg shadow-orange-600/30"
                >
                  ZALOGUJ
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* FILTRY */}
      {surveys.length > 0 && (
        <div className="bg-slate-900 text-white border-b border-slate-800 py-4 shadow-xl">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-wrap items-center gap-8">
            <div className="flex items-center gap-3">
              <label className="text-[10px] uppercase font-black text-slate-500 tracking-tighter">Rok:</label>
              <select 
                value={selectedYear} 
                onChange={(e) => setSelectedYear(e.target.value)}
                className="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-xs font-bold outline-none focus:ring-1 focus:ring-orange-500"
              >
                <option value="all">Wszystkie</option>
                <option value="2024">2024</option>
                <option value="2025">2025</option>
              </select>
            </div>

            <div className="flex items-center gap-3">
              <label className="text-[10px] uppercase font-black text-slate-500 tracking-tighter">Kwartał:</label>
              <div className="flex bg-slate-800 p-1 rounded-xl gap-1">
                {['all', 'I', 'II', 'III', 'IV'].map(q => (
                  <button 
                    key={q} 
                    onClick={() => setSelectedQuarter(q)}
                    className={`px-3 py-1 text-[10px] font-black rounded-lg transition-all ${selectedQuarter === q ? 'bg-orange-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                  >
                    {q === 'all' ? 'WSZYSTKIE' : q}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex items-center gap-3 flex-1 min-w-[200px]">
              <label className="text-[10px] uppercase font-black text-slate-500 tracking-tighter">Zbiór danych:</label>
              <div className="flex gap-2 flex-1">
                <select 
                  value={selectedFile} 
                  onChange={(e) => setSelectedFile(e.target.value)}
                  className="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-xs font-bold flex-1 outline-none text-orange-400"
                >
                  <option value="all">Wszystkie wgrane pliki</option>
                  {uniqueFiles.map(f => <option key={f} value={f}>{f}</option>)}
                </select>
                {isAdmin && selectedFile !== 'all' && (
                  <button 
                    onClick={deleteSelectedFileSet}
                    className="bg-red-900/30 text-red-500 border border-red-900/50 px-3 py-1.5 rounded-lg text-[10px] font-black hover:bg-red-600 hover:text-white transition-all"
                  >
                    USUŃ ZBIÓR
                  </button>
                )}
              </div>
            </div>

            <div className="text-[11px] font-black">
              WIDOK: <span className="text-orange-500">{filteredSurveys.length}</span> / {surveys.length} ANKIET
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === AppTab.UPLOAD && isAdmin ? (
          <div className="animate-in fade-in duration-500 slide-in-from-top-4">
            <SurveyUploader onDataLoaded={handleDataLoaded} />
          </div>
        ) : filteredSurveys.length > 0 ? (
          <div className="animate-in fade-in duration-500">
            {activeTab === AppTab.SUMMARY && <SummaryDashboard surveys={filteredSurveys} />}
            {activeTab === AppTab.TABLE && <DetailedTableView surveys={filteredSurveys} />}
            {activeTab === AppTab.EDA && <EDADashboard surveys={filteredSurveys} />}
          </div>
        ) : (
          <div className="bg-white rounded-3xl border border-slate-200 p-20 text-center shadow-sm">
             <i className="fa-solid fa-inbox text-6xl text-slate-100 mb-6"></i>
             <h2 className="text-2xl font-black text-slate-800 tracking-tight">Brak danych do wyświetlenia</h2>
             <p className="text-slate-500 mt-3 max-w-md mx-auto font-medium">
               {isAdmin ? "Wgraj pierwsze ankiety w zakładce 'Nowe Dane'." : "Baza jest obecnie pusta. Poczekaj na wgranie danych przez Administratora."}
             </p>
          </div>
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-10 text-center">
        <div className="text-slate-400 text-[10px] uppercase font-black tracking-[0.2em]">
          QUEST SURVEY INSIGHTS © {new Date().getFullYear()}
        </div>
        <div className="mt-2 inline-flex items-center gap-2 px-3 py-1 bg-slate-100 rounded-full text-[9px] font-bold text-slate-500">
          <i className={`fa-solid ${isAdmin ? 'fa-unlock text-orange-500' : 'fa-lock'}`}></i>
          Tryb: {isAdmin ? 'ADMINISTRATOR' : 'GOŚĆ'}
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { SurveyRecord } from '../types';

interface DetailedTableViewProps {
  surveys: SurveyRecord[];
}

export const DetailedTableView: React.FC<DetailedTableViewProps> = ({ surveys }) => {
  const getColor = (val: number | null): string => {
    if (!val) return 'bg-slate-50 text-slate-300';
    if (val >= 5.5) return 'bg-orange-600 text-white';
    if (val >= 5) return 'bg-green-100 text-green-700';
    if (val >= 4) return 'bg-blue-50 text-blue-700';
    if (val >= 3) return 'bg-yellow-50 text-yellow-700';
    return 'bg-red-50 text-red-700';
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">ID</th>
              <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Szkolenie / Lokalizacja</th>
              <th className="px-2 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Org</th>
              <th className="px-2 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Met</th>
              <th className="px-2 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Pra</th>
              <th className="px-2 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Mat</th>
              <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Średnia Kadry</th>
              <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Komentarz</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {surveys.map((s, idx) => {
              const trainerVals: number[] = [];
              Object.values(s.trainerRatings).forEach(tr => {
                [tr.knowledge, tr.didactics, tr.preparation, tr.engagement, tr.culture].forEach(v => {
                  if (v !== null) trainerVals.push(v);
                });
              });
              const trainerAvg = trainerVals.length ? (trainerVals.reduce((a, b) => a + b, 0) / trainerVals.length).toFixed(2) : '-';

              return (
                <tr key={s.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-6 text-[11px] font-black text-slate-300">#{idx + 1}</td>
                  <td className="px-6 py-6">
                    <div className="text-sm font-black text-slate-800 truncate max-w-[250px]" title={s.trainingTitle}>{s.trainingTitle || 'Analiza w toku...'}</div>
                    <div className="text-[10px] text-slate-400 mt-1 font-bold uppercase tracking-tighter">{s.date} • {s.place}</div>
                  </td>
                  <td className="px-2 py-6 text-center">
                     <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg font-black text-xs ${getColor(s.ratings.organization)} shadow-sm`}>{s.ratings.organization || '-'}</span>
                  </td>
                  <td className="px-2 py-6 text-center">
                     <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg font-black text-xs ${getColor(s.ratings.methods)} shadow-sm`}>{s.ratings.methods || '-'}</span>
                  </td>
                  <td className="px-2 py-6 text-center">
                     <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg font-black text-xs ${getColor(s.ratings.practicality)} shadow-sm`}>{s.ratings.practicality || '-'}</span>
                  </td>
                  <td className="px-2 py-6 text-center">
                     <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg font-black text-xs ${getColor(s.ratings.materialsMerit)} shadow-sm`}>{s.ratings.materialsMerit || '-'}</span>
                  </td>
                  <td className="px-6 py-6">
                    <div className="flex items-center gap-3">
                      <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden max-w-[60px]">
                        <div className="h-full bg-orange-500" style={{ width: trainerAvg !== '-' ? `${(parseFloat(trainerAvg)/6)*100}%` : '0%' }}></div>
                      </div>
                      <span className="text-xs font-black text-slate-700">{trainerAvg}</span>
                    </div>
                  </td>
                  <td className="px-6 py-6">
                    <p className="text-[11px] text-slate-500 line-clamp-2 italic max-w-xs group-hover:text-slate-800 transition-colors leading-relaxed">
                      {s.comments.positive || s.comments.suggestions || 'Brak komentarza'}
                    </p>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React from 'react';
import { SurveyRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar } from 'recharts';

interface EDADashboardProps {
  surveys: SurveyRecord[];
}

export const EDADashboard: React.FC<EDADashboardProps> = ({ surveys }) => {
  const avg = (arr: (number | null)[]) => {
    const valid = arr.filter(v => v !== null && !isNaN(v as number));
    return valid.length ? parseFloat((valid.reduce((a, b) => a + b, 0) / valid.length).toFixed(2)) : 0;
  };

  const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

  const mainData = [
    { name: 'Organizacja', score: avg(surveys.map(s => s.ratings.organization)) },
    { name: 'Metody', score: avg(surveys.map(s => s.ratings.methods)) },
    { name: 'Praktyka', score: avg(surveys.map(s => s.ratings.practicality)) },
    { name: 'Przejrzystość', score: avg(surveys.map(s => s.ratings.materialsClarity)) },
    { name: 'Merytoryka', score: avg(surveys.map(s => s.ratings.materialsMerit)) },
  ];

  const trainers = ['luiza', 'krzysztof', 'anna', 'tomasz'] as const;
  const trainerData = trainers.map(t => ({
    name: capitalize(t),
    merytoryka: avg(surveys.map(s => s.trainerRatings[t].knowledge)),
    dydaktyka: avg(surveys.map(s => s.trainerRatings[t].didactics)),
    komunikacja: avg(surveys.map(s => s.trainerRatings[t].engagement)),
  })).filter(t => t.merytoryka > 0);

  return (
    <div className="space-y-8 pb-10">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Kryteria Główne */}
        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 mb-8 uppercase tracking-widest flex items-center gap-2">
            <i className="fa-solid fa-chart-simple text-orange-500"></i> Kryteria Główne
          </h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={mainData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }} />
                <YAxis domain={[0, 6]} axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#cbd5e1' }} />
                <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                <Bar dataKey="score" fill="#ea580c" radius={[8, 8, 0, 0]} barSize={40} name="Średnia" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Porównanie Trenerów */}
        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 mb-8 uppercase tracking-widest flex items-center gap-2">
            <i className="fa-solid fa-users text-blue-500"></i> Porównanie Trenerów
          </h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trainerData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }} />
                <YAxis domain={[0, 6]} axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#cbd5e1' }} />
                <Tooltip cursor={{ fill: '#f8fafc' }} />
                <Legend iconType="circle" wrapperStyle={{ paddingTop: '20px', fontSize: '10px', fontWeight: 800, textTransform: 'uppercase' }} />
                <Bar dataKey="merytoryka" fill="#3b82f6" radius={[4, 4, 0, 0]} name="Wiedza" />
                <Bar dataKey="dydaktyka" fill="#8b5cf6" radius={[4, 4, 0, 0]} name="Metodyka" />
                <Bar dataKey="komunikacja" fill="#10b981" radius={[4, 4, 0, 0]} name="Kontakt" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Radar Chart */}
      <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm flex flex-col items-center">
        <h3 className="text-sm font-black text-slate-800 mb-2 uppercase tracking-widest">Pełna Charakterystyka Jakości</h3>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-10">Zintegrowany widok wszystkich wymiarów</p>
        <div className="h-[400px] w-full">
           <ResponsiveContainer width="100%" height="100%">
             <RadarChart cx="50%" cy="50%" outerRadius="80%" data={[
               { subject: 'Organizacja', value: avg(surveys.map(s => s.ratings.organization)) },
               { subject: 'Metody', value: avg(surveys.map(s => s.ratings.methods)) },
               { subject: 'Praktyka', value: avg(surveys.map(s => s.ratings.practicality)) },
               { subject: 'Materiały', value: avg(surveys.map(s => s.ratings.materialsMerit)) },
               { subject: 'Kadra: Wiedza', value: avg(surveys.map(s => Math.max(...trainers.map(t => s.trainerRatings[t].knowledge || 0)))) },
               { subject: 'Kadra: Kultura', value: avg(surveys.map(s => Math.max(...trainers.map(t => s.trainerRatings[t].culture || 0)))) },
             ]}>
               <PolarGrid stroke="#e2e8f0" />
               <PolarAngleAxis dataKey="subject" tick={{ fontSize: 9, fontWeight: 800, fill: '#64748b' }} />
               <PolarRadiusAxis angle={30} domain={[0, 6]} tick={{ fontSize: 8 }} />
               <Radar name="Ocena" dataKey="value" stroke="#ea580c" fill="#ea580c" fillOpacity={0.6} />
               <Tooltip />
             </RadarChart>
           </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

