import { GoogleGenAI, Type } from "@google/genai";
import { SurveyRecord, TRAINER_MAP } from "../types";

const SYSTEM_INSTRUCTION = `
Jesteś zaawansowanym systemem OCR wyspecjalizowanym w analizie ankiet papierowych firmy "QUEST". 
Twoim zadaniem jest przekształcenie obrazów lub dokumentów PDF na ustrukturyzowane dane JSON.

ZASADY ANALIZY:
1. IDENTYFIKACJA ANKIET: Na jednej stronie może znajdować się jedna lub więcej ankiet. Wyodrębnij KAŻDĄ z nich jako osobny obiekt w tablicy "surveys".
2. OCENY: Szukaj zakreślonych kółek, krzyżyków lub podkreśleń przy cyfrach 1-6. Jeśli ocena jest niejednoznaczna, wybierz najbardziej prawdopodobną lub wpisz null.
3. TRENERZY: W ankiecie są sekcje dla trenerów. Zidentyfikuj, który trener jest oceniany. Możliwe osoby to: ${Object.values(TRAINER_MAP).join(", ")}.
4. MAPOWANIE KLUCZY: W JSON użyj następujących kluczy dla trenerów: ${Object.keys(TRAINER_MAP).join(", ")}.
5. PISMO RĘCZNE: Przepisz komentarze (Plusy, Minusy, Sugestie) słowo w słowo. Jeśli pismo jest nieczytelne, wpisz "[nieczytelne]".
6. DATY I MIEJSCA: Zidentyfikuj datę szkolenia (format DD.MM.YYYY) oraz tytuł szkolenia i miejsce.

STRUKTURA WYJŚCIOWA (JSON):
{
  "surveys": [
    {
      "trainingTitle": "string",
      "date": "string",
      "place": "string",
      "ratings": { "organization": number|null, "methods": number|null, "practicality": number|null, "materialsClarity": number|null, "materialsMerit": number|null },
      "trainerRatings": {
        "identyfikator_trenera_1": { "knowledge": n|null, "didactics": n|null, "preparation": n|null, "engagement": n|null, "culture": n|null },
        "identyfikator_trenera_2": { ... }
      },
      "comments": { "positive": "string", "negative": "string", "suggestions": "string" }
    }
  ]
}

WAŻNE: Nie dodawaj żadnego tekstu przed ani po JSON. Jeśli nie znajdziesz żadnych ankiet, zwróć {"surveys": []}.
`;

export async function processSurveyFiles(files: { data: string, mimeType: string }[]): Promise<SurveyRecord[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const mediaParts = files.map(file => ({
    inlineData: {
      mimeType: file.mimeType,
      data: file.data
    }
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          ...mediaParts,
          { text: "Przeanalizuj te dokumenty i wyodrębnij wszystkie dane ankietowe do formatu JSON. Bardzo ważne jest rozpoznanie, który trener z listy QUEST jest oceniany w danej sekcji." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 16000 }
      }
    });

    const rawText = response.text || "";
    let jsonStr = rawText.trim();
    if (jsonStr.includes('```')) {
      const match = jsonStr.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
      if (match) jsonStr = match[1];
    }

    const firstBrace = jsonStr.indexOf('{');
    const lastBrace = jsonStr.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
      jsonStr = jsonStr.substring(firstBrace, lastBrace + 1);
    }

    if (!jsonStr) throw new Error("Błąd formatowania odpowiedzi AI.");
    const result = JSON.parse(jsonStr);

    const surveys = result.surveys || (Array.isArray(result) ? result : []);

    return surveys.map((s: any, idx: number) => ({
      ...s,
      id: `${Date.now()}-${idx}-${Math.random().toString(36).substring(2, 7)}`
    }));
  } catch (error: any) {
    console.error("Gemini Service Error:", error);
    throw error;
  }
}

