  const deleteSelectedFileSet = () => {
    if (!isAdmin || selectedFile === 'all') return;

    const countToDelete = surveys.filter(s => s.fileName === selectedFile).length;

    if (confirm(`Zbiór "${selectedFile}" zawiera ${countToDelete} ankiet. Czy na pewno chcesz go TRWALE usunąć?`)) {
      const remainingSurveys = surveys.filter(s => s.fileName !== selectedFile);
      setSurveys(remainingSurveys);
      setSelectedFile('all');

      // Natychmiastowa aktualizacja storage dla pewności
      localStorage.setItem(STORAGE_KEY, JSON.stringify(remainingSurveys));

      if (remainingSurveys.length === 0) {
        setActiveTab(AppTab.UPLOAD);
      }
    }
  };

  const clearAllData = () => {
    if (!isAdmin) return;
    if (confirm("UWAGA: Ta operacja nieodwracalnie usunie WSZYSTKIE ankiety z bazy. Kontynuować?")) {
      setSurveys([]);
      setSelectedFile('all');
      localStorage.setItem(STORAGE_KEY, JSON.stringify([]));
      setActiveTab(AppTab.UPLOAD);
