               <PolarRadiusAxis angle={30} domain={[0, 6]} tick={{ fontSize: 8 }} axisLine={false} />
               <Radar name="Skala Ocen" dataKey="value" stroke="#ea580c" fill="#ea580c" fillOpacity={0.5} />
