             {isAdmin && (
               <button onClick={() => setActiveTab(AppTab.UPLOAD)} className="mt-8 px-8 py-3 bg-orange-600 text-white font-black text-xs rounded-2xl hover:bg-orange-700 transition-all shadow-lg shadow-orange-600/20 uppercase">
