import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  addDoc, 
  getDocs, 
  deleteDoc, 
  query, 
  where, 
  doc,
  writeBatch
} from "firebase/firestore";
import { SurveyRecord } from "../types";

const firebaseConfig = {
  apiKey: "AIzaSyBKj1pCHwlOR7-m3sQ0Zw8Z8qBzoEkxzw4",
  authDomain: "quest-analytics-a32c1.firebaseapp.com",
  projectId: "quest-analytics-a32c1",
  storageBucket: "quest-analytics-a32c1.firebasestorage.app",
  messagingSenderId: "644793982514",
  appId: "1:644793982514:web:48b4b657ff905895e4e62b",
  measurementId: "G-4DH57QMS4L"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);
const surveysCol = collection(db, "surveys");

export const firebaseService = {
  async getAllSurveys(): Promise<SurveyRecord[]> {
    try {
      const snapshot = await getDocs(surveysCol);
      return snapshot.docs.map(doc => ({
        ...doc.data(),
        id: doc.id
      } as SurveyRecord));
    } catch (error) {
      console.error("Firestore Error (Get):", error);
      return [];
    }
  },

  async addSurveys(newSurveys: SurveyRecord[], fileName: string): Promise<void> {
    try {
      const batch = writeBatch(db);
      newSurveys.forEach(survey => {
        const docRef = doc(surveysCol);
        batch.set(docRef, { ...survey, fileName });
      });
      await batch.commit();
    } catch (error) {
      console.error("Firestore Error (Add):", error);
      throw error;
    }
  },

  async deleteSurveysByFileName(fileName: string): Promise<void> {
    try {
      const q = query(surveysCol, where("fileName", "==", fileName));
      const snapshot = await getDocs(q);
      const batch = writeBatch(db);
      snapshot.docs.forEach((d) => {
        batch.delete(d.ref);
      });
      await batch.commit();
    } catch (error) {
      console.error("Firestore Error (Delete File):", error);
      throw error;
    }
  },

  async clearAllData(): Promise<void> {
    try {
      const snapshot = await getDocs(surveysCol);
      const batch = writeBatch(db);
      snapshot.docs.forEach((d) => {
        batch.delete(d.ref);
      });
      await batch.commit();
    } catch (error) {
      console.error("Firestore Error (Clear All):", error);
      throw error;
    }
  }
};

